return ['domain'=>'vireo-analytics','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'Vireo Analytics 0.3.2','pot-creation-date'=>'2026-10-15T14:42:49+00:00','po-revision-date'=>'2026-07-18T10:06:34+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Vireo Analytics'=>'Vireo Analytics','Privacy-first WordPress analytics. Clean dashboard, no cookies, no consent banners, no third-party tracking.'=>'Privacyvriendelijke WordPress-analytics. Overzichtelijk dashboard, geen cookies, geen toestemmingsbanners, geen tracking door derden.','RebelCode'=>'RebelCode','https://rebelcode.com'=>'https://rebelcode.com','Vireo Analytics backup'=>'Vireo Analytics-back-up','That file is larger than this server accepts (%s). Ask your host to raise the upload limit, or restore in smaller pieces.'=>'Dat bestand is groter dan deze server toestaat (%s). Vraag je host om de uploadlimiet te verhogen, of herstel in kleinere delen.','The upload did not complete. Try again.'=>'De upload is niet voltooid. Probeer het opnieuw.','The uploads directory is not writable, so the file cannot be kept while it is read.'=>'De uploadmap is niet beschrijfbaar, dus het bestand kan niet worden bewaard terwijl het wordt gelezen.','The file could not be saved for reading.'=>'Het bestand kon niet worden opgeslagen om te worden gelezen.','The file could not be opened.'=>'Het bestand kon niet worden geopend.','The file is damaged: a line could not be read.'=>'Het bestand is beschadigd: een regel kon niet worden gelezen.','The file ends early. It may not have finished downloading; export it again.'=>'Het bestand eindigt te vroeg. Mogelijk is het downloaden niet voltooid; exporteer het opnieuw.','That is not a Vireo Analytics backup. Use the file from Settings, Import & export, Download backup.'=>'Dat is geen Vireo Analytics-back-up. Gebruik het bestand via Instellingen, Importeren en exporteren, Back-up downloaden.','This backup was made by a newer version of Vireo Analytics. Update the plugin here, then try again.'=>'Deze back-up is gemaakt met een nieuwere versie van Vireo Analytics. Werk de plugin hier bij en probeer het daarna opnieuw.','Upload a backup file first.'=>'Upload eerst een back-upbestand.','The uploaded file is no longer available. Upload it again.'=>'Het geüploade bestand is niet meer beschikbaar. Upload het opnieuw.','Restored. %d part of the file was for a table this version does not have and was skipped.'=>'Hersteld. %d deel van het bestand was voor een tabel die deze versie niet heeft en is overgeslagen.' . "\0" . 'Hersteld. %d delen van het bestand waren voor tabellen die deze versie niet heeft en zijn overgeslagen.','Restored.'=>'Hersteld.','Restoring %s'=>'%s herstellen','daily totals'=>'dagtotalen','bounce rates'=>'bouncepercentages','hourly totals'=>'uurtotalen','pages'=>'pagina\'s','time on page'=>'tijd op pagina','referrers'=>'verwijzingen','referrers per page'=>'verwijzers per pagina','countries'=>'landen','devices'=>'apparaten','missing pages'=>'ontbrekende pagina\'s','events'=>'gebeurtenissen','bot traffic'=>'botverkeer','Core Web Vitals'=>'Core Web Vitals','chart notes'=>'grafieknotities','Search Console queries'=>'Search Console-zoekopdrachten','Search Console pages'=>'Search Console-pagina\'s','Burst Statistics'=>'Burst Statistics','No Burst Statistics data found.'=>'Geen gegevens gevonden voor Burst Statistics.','Burst Statistics import complete.'=>'Import van Burst Statistics voltooid.','Imported %1$d of %2$d day from Burst Statistics.'=>'%1$d van %2$d dag geïmporteerd uit Burst Statistics.' . "\0" . '%1$d van %2$d dagen geïmporteerd uit Burst Statistics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices and missing pages.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, je pagina\'s, verwijzingen, naar welke berichten elke verwijzer lezers heeft gestuurd, landen, browsers, besturingssystemen, apparaten en ontbrekende pagina\'s.','Google Analytics 4'=>'Google Analytics 4','Add the service account key and the GA4 property ID first.'=>'Voeg eerst de serviceaccountsleutel en het GA4-property-ID toe.','The date range is not valid.'=>'De periode is niet geldig.','Imported %1$s to %2$s'=>'Geïmporteerd van %1$s tot %2$s','Google refused the request. Check the service account has Viewer access on this GA4 property.'=>'Google heeft het verzoek geweigerd. Controleer of het serviceaccount Kijker-toegang heeft tot deze GA4-property.','Google Analytics returned an unexpected response (HTTP %d).'=>'Google Analytics gaf een onverwachte reactie (HTTP %d).','Google Analytics returned a response we could not read.'=>'Google Analytics gaf een reactie die we niet konden lezen.','Import complete'=>'Import voltooid','Import stopped'=>'Import gestopt','Independent Analytics'=>'Independent Analytics','No Independent Analytics data found.'=>'Geen gegevens gevonden voor Independent Analytics.','Independent Analytics import complete.'=>'Import van Independent Analytics voltooid.','Imported %1$d of %2$d day from Independent Analytics.'=>'%1$d van %2$d dag geïmporteerd uit Independent Analytics.' . "\0" . '%1$d van %2$d dagen geïmporteerd uit Independent Analytics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, and tracked link clicks and form submissions as events.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, je pagina\'s, verwijzingen, naar welke berichten elke verwijzer lezers heeft gestuurd, landen, browsers, besturingssystemen, apparaten, ontbrekende pagina\'s, en gevolgde linkklikken en formulierinzendingen als gebeurtenissen.','Jetpack Stats'=>'Jetpack Stats','Importing %1$s — %2$s'=>'%1$s — %2$s importeren','Missing import parameters. Please submit the form again.'=>'Ontbrekende importparameters. Verstuur het formulier opnieuw.','Invalid date range — please use YYYY-MM-DD.'=>'Ongeldig datumbereik, gebruik JJJJ-MM-DD.','End date must be on or after start date.'=>'De einddatum moet op of na de startdatum liggen.','Complete'=>'Voltooid','Could not reach Jetpack Stats API: %s'=>'Kan de Jetpack Stats-API niet bereiken: %s','Unexpected (non-JSON) response from Jetpack Stats API.'=>'Onverwacht (niet-JSON) antwoord van de Jetpack Stats-API.','Invalid or unauthorized API key. Copy your WordPress.com API key from Jetpack → Settings → Security → Akismet.'=>'Ongeldige of niet-geautoriseerde API-sleutel. Kopieer je WordPress.com-API-sleutel via Jetpack → Instellingen → Beveiliging → Akismet.','Jetpack Stats API is rate-limiting — please wait a minute and try again.'=>'De Jetpack Stats-API beperkt het aantal verzoeken. Wacht een minuut en probeer het opnieuw.','Jetpack Stats API is unavailable right now. Please retry in a few minutes.'=>'De Jetpack Stats-API is momenteel niet beschikbaar. Probeer het over een paar minuten opnieuw.','Jetpack Stats API returned an error (HTTP %d). Check your API key and blog URI.'=>'De Jetpack Stats-API gaf een fout terug (HTTP %d). Controleer je API-sleutel en blog-URI.','Koko Analytics'=>'Koko Analytics','No Koko Analytics data found.'=>'Geen Koko Analytics-gegevens gevonden.','Plausible Analytics'=>'Plausible Analytics','No Plausible reports were found in that upload. Upload the zip file Plausible emailed you, or the CSV files inside it.'=>'Er zijn geen Plausible-rapporten gevonden in die upload. Upload het zipbestand dat Plausible je heeft gemaild, of de CSV-bestanden erin.','The export has no traffic in the dates you chose.'=>'De export bevat geen verkeer in de datums die je hebt gekozen.','Upload a Plausible export first.'=>'Upload eerst een Plausible-export.','The uploaded export is no longer available. Upload it again; dates already imported are listed on this screen.'=>'De geüploade export is niet meer beschikbaar. Upload hem opnieuw; datums die al zijn geïmporteerd staan op dit scherm.','The file did not upload. It may be larger than this server accepts.'=>'Het bestand is niet geüpload. Het is mogelijk groter dan deze server toestaat.','That file is too large. Export a shorter date range from Plausible and import it in parts.'=>'Dat bestand is te groot. Exporteer een kortere periode uit Plausible en importeer die in delen.','Upload the .zip file Plausible gave you, or the .csv files inside it.'=>'Upload het .zip-bestand dat Plausible je heeft gegeven, of de .csv-bestanden erin.','The uploaded file could not be read.'=>'Het geüploade bestand kon niet worden gelezen.','This server cannot open zip files. Unzip the export on your computer and upload the CSV files instead.'=>'Deze server kan geen zipbestanden openen. Pak de export uit op je computer en upload in plaats daarvan de CSV-bestanden.','That zip file could not be opened.'=>'Dat zipbestand kon niet worden geopend.','That zip holds more files than a Plausible export does.'=>'Dat zipbestand bevat meer bestanden dan een Plausible-export.','A file inside the zip could not be read.'=>'Een bestand in het zipbestand kon niet worden gelezen.','The %1$s file is missing its %2$s column.'=>'Het bestand %1$s mist de kolom %2$s.','That export is too large to import in one go. Choose a shorter date range and import it in parts.'=>'Die export is te groot om in één keer te importeren. Kies een kortere periode en importeer in delen.','SlimStat Analytics'=>'SlimStat Analytics','No SlimStat data found.'=>'Geen gegevens gevonden voor SlimStat.','SlimStat import complete.'=>'Import van SlimStat voltooid.','Imported %1$d of %2$d day from SlimStat.'=>'%1$d van %2$d dag geïmporteerd uit SlimStat.' . "\0" . '%1$d van %2$d dagen geïmporteerd uit SlimStat.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, downloads and outbound clicks, and the crawlers SlimStat recorded, as filtered bots rather than visits.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, je pagina\'s, verwijzingen, naar welke berichten elke verwijzer lezers heeft gestuurd, landen, browsers, besturingssystemen, apparaten, ontbrekende pagina\'s, downloads en uitgaande klikken, en de crawlers die SlimStat heeft geregistreerd, als gefilterde bots in plaats van bezoeken.','Statify'=>'Statify','No Statify data found.'=>'Geen gegevens gevonden voor Statify.','Statify import complete.'=>'Import van Statify voltooid.','Imported %1$d of %2$d day from Statify.'=>'%1$d van %2$d dag geïmporteerd uit Statify.' . "\0" . '%1$d van %2$d dagen geïmporteerd uit Statify.','Brings across daily pageviews, your pages, referrers and which posts each referrer sent readers to. Statify does not identify visitors, so imported days have no visitor counts.'=>'Neemt dagelijkse paginaweergaven, je pagina\'s, verwijzingen en naar welke berichten elke verwijzer lezers heeft gestuurd over. Statify identificeert geen bezoekers, dus geïmporteerde dagen hebben geen aantallen bezoekers.','WP Statistics'=>'WP Statistics','No WP Statistics data found.'=>'Geen gegevens gevonden voor WP Statistics.','WP Statistics import complete.'=>'Import van WP Statistics voltooid.','Imported %1$d of %2$d day from WP Statistics.'=>'%1$d van %2$d dag geïmporteerd uit WP Statistics.' . "\0" . '%1$d van %2$d dagen geïmporteerd uit WP Statistics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, link clicks, downloads and custom events, and, if WP Statistics recorded exclusions, the bots it filtered out.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, je pagina\'s, verwijzingen, naar welke berichten elke verwijzer lezers heeft gestuurd, landen, browsers, besturingssystemen, apparaten, ontbrekende pagina\'s, linkklikken, downloads en aangepaste gebeurtenissen, en, als WP Statistics uitsluitingen heeft geregistreerd, de bots die het heeft gefilterd.','Read-only site analytics: traffic, pages, referrers, geography, devices, and events.'=>'Alleen-lezen site-analytics: verkeer, pagina\'s, verwijzingen, geografie, apparaten en gebeurtenissen.','Get traffic totals'=>'Verkeerstotalen ophalen','Total pageviews, unique visitors, average daily pageviews, average time on page and bounce rate for a date range (defaults to the last 30 days). Time on page is active time (the tab in front of the reader, at most 30 minutes a view), averaged over the views that reported one. Bounce rate is the percentage of visitors who viewed exactly one page in a day. Both are null until there is data for the range.'=>'Totaal aantal paginaweergaven, unieke bezoekers, gemiddeld aantal paginaweergaven per dag, gemiddelde tijd op de pagina en bouncepercentage voor een datumbereik (standaard de laatste 30 dagen). Tijd op de pagina is actieve tijd (het tabblad staat vooraan bij de lezer, maximaal 30 minuten per weergave), gemiddeld over de weergaven die een tijd hebben doorgegeven. Het bouncepercentage is het percentage bezoekers dat op één dag precies één pagina heeft bekeken. Beide zijn null zolang er geen gegevens voor het bereik zijn.','Get daily traffic series'=>'Dagelijkse verkeersreeks ophalen','Per-day pageviews and visitors over a date range, for charting trends.'=>'Paginaweergaven en bezoekers per dag over een datumbereik, om trends in een grafiek te zetten.','Get top pages'=>'Toppagina\'s ophalen','Most-viewed pages for a date range, ranked by pageviews, with each page\'s average active time on page in seconds (null when no view of it reported a time).'=>'Meest bekeken pagina\'s voor een datumbereik, gerangschikt op paginaweergaven, met de gemiddelde actieve tijd op de pagina in seconden per pagina (null als geen enkele weergave een tijd heeft doorgegeven).','Get top referrers'=>'Belangrijkste verwijzingen ophalen','Top referring sites sending traffic for a date range.'=>'Belangrijkste verwijzende sites die verkeer sturen voor een datumbereik.','Get traffic by country'=>'Verkeer per land ophalen','Visitor counts broken down by country for a date range.'=>'Aantal bezoekers uitgesplitst per land voor een datumbereik.','Get device breakdown'=>'Apparaatverdeling ophalen','Visitor breakdown by browser, operating system, and device type for a date range.'=>'Bezoekersverdeling per browser, besturingssysteem en apparaattype voor een datumbereik.','Get custom events'=>'Aangepaste gebeurtenissen ophalen','Top custom events for a date range. Pass a `name` to break a single event down by value.'=>'Belangrijkste aangepaste gebeurtenissen voor een datumbereik. Geef een `name` op om één gebeurtenis uit te splitsen per waarde.','Optional event name to break down by value.'=>'Optionele gebeurtenisnaam om uit te splitsen per waarde.','Get stats for a post'=>'Statistieken voor een bericht ophalen','Lifetime and date-range pageviews/visitors, a daily series, and the top referrers for a single post or page. Use get-top-pages first if you only have a title or path.'=>'Pageviews/bezoekers over de hele looptijd en voor een datumbereik, een dagelijkse reeks en de top-verwijzers voor één bericht of pagina. Gebruik eerst get-top-pages als je alleen een titel of pad hebt.','The post or page ID to report on.'=>'Het bericht- of pagina-ID waarover je wilt rapporteren.','Get hourly traffic series'=>'Verkeer per uur ophalen','Pageviews and visitors per hour, for "what time of day do people visit" and for looking at today or yesterday in detail. Covers at most two days; longer ranges are cut to the last two days. Defaults to today.'=>'Pageviews en bezoekers per uur, voor "op welk moment van de dag bezoeken mensen de site" en om vandaag of gisteren in detail te bekijken. Beslaat maximaal twee dagen; langere bereiken worden ingekort tot de laatste twee dagen. Standaard vandaag.','Get what changed'=>'Wijzigingen ophalen','What changed against the previous period of the same length: a one-sentence summary, the pages and traffic sources that gained or lost the most, shifts in the traffic mix, and health warnings such as tracking having stopped or a 404 spike. Call this first when asked "how is the site doing" or "why is traffic up/down".'=>'Wat er is veranderd ten opzichte van de vorige periode van dezelfde lengte: een samenvatting in één zin, de pagina\'s en verkeersbronnen met de grootste toename of afname, verschuivingen in de verkeersmix en waarschuwingen over de gezondheid, zoals gestopte tracking of een piek in 404\'s. Roep dit eerst aan als iemand vraagt "hoe gaat het met de site" of "waarom is het verkeer gestegen/gedaald".','Get weekly highlights'=>'Wekelijkse highlights ophalen','Short, ready-to-quote highlights for a finished week: milestones crossed, the biggest gaining page, a new referrer, the best day. Defaults to the last seven full days. Returns an empty list when nothing stood out.'=>'Korte, direct bruikbare highlights voor een afgelopen week: bereikte mijlpalen, de pagina met de grootste toename, een nieuwe verwijzer, de beste dag. Standaard de laatste zeven volledige dagen. Geeft een lege lijst terug als er niets bijzonders was.','Get traffic by channel'=>'Verkeer per kanaal ophalen','Pageviews and visitors grouped by how people arrived: direct, search engines, AI assistants, social networks, and other referring sites, with each channel\'s share. Use get-top-referrers for the individual sites inside a channel.'=>'Pageviews en bezoekers gegroepeerd op hoe mensen binnenkwamen: direct, zoekmachines, AI-assistenten, sociale netwerken en andere verwijzende sites, met het aandeel van elk kanaal. Gebruik get-top-referrers voor de afzonderlijke sites binnen een kanaal.','Get stats for one referrer'=>'Statistieken van één verwijzer ophalen','Everything about traffic from one referring site: pageviews and visitors in the range, a daily series, and which of your pages it sent people to. Pass the host as shown by get-top-referrers, for example "news.ycombinator.com".'=>'Alles over het verkeer van één verwijzende site: pageviews en bezoekers in het bereik, een dagelijkse reeks en naar welke van je pagina\'s die site mensen heeft gestuurd. Geef de host door zoals get-top-referrers die toont, bijvoorbeeld "news.ycombinator.com".','The referring site, as a hostname or URL.'=>'De verwijzende site, als hostnaam of URL.','Get AI assistant traffic'=>'Verkeer van AI-assistenten ophalen','What AI assistants take and what they send back: requests made by AI crawlers (GPTBot, ClaudeBot, PerplexityBot and others) against readers (visitors) that ChatGPT, Claude, Perplexity, Gemini and the rest referred to the site, per assistant, with the ratio of crawler requests per reader sent. Everything covers the days crawlers were counted; when that starts later than the requested range, `since` holds that date.'=>'Wat AI-assistenten ophalen en wat ze terugsturen: verzoeken van AI-crawlers (GPTBot, ClaudeBot, PerplexityBot en andere) tegenover lezers (bezoekers) die ChatGPT, Claude, Perplexity, Gemini en de rest naar de site hebben verwezen, per assistent, met de verhouding tussen crawlerverzoeken per gestuurde lezer. Alles heeft betrekking op de dagen waarop crawlers werden geteld; als dat later begint dan de gevraagde periode, bevat `since` die datum.','Get Google Search Console data'=>'Google Search Console-gegevens ophalen','Google Search performance synced from Search Console: site-wide clicks, impressions, CTR and average position plus the top search queries, or, when post_id or path is given, the queries that brought people to that one page. Returns connected=false with no data when Search Console is not connected under Settings. Google\'s data lags two to three days behind.'=>'Prestaties in Google Zoeken, gesynchroniseerd vanuit Search Console: klikken, vertoningen, CTR en gemiddelde positie van de hele site plus de top zoekopdrachten, of, als post_id of path is opgegeven, de zoekopdrachten die mensen naar die ene pagina brachten. Geeft connected=false zonder gegevens terug als Search Console niet is gekoppeld onder Instellingen. De gegevens van Google lopen twee tot drie dagen achter.','Optional post or page ID to get the queries for that page only.'=>'Optioneel bericht- of pagina-ID om alleen de zoekopdrachten voor die pagina op te halen.','Optional page path (for example /pricing) instead of post_id.'=>'Optioneel pagina-pad (bijvoorbeeld /pricing) in plaats van post_id.','Get stats for one event'=>'Statistieken van één gebeurtenis ophalen','One custom event in depth: total and unique counts, a daily series, how many distinct values it carried, and the top values. Use get-events to find event names first.'=>'Eén aangepaste gebeurtenis in detail: totaal en unieke aantallen, een dagelijkse reeks, hoeveel verschillende waarden de gebeurtenis bevatte en de top waarden. Gebruik eerst get-events om gebeurtenisnamen te vinden.','The event name, as listed by get-events.'=>'De naam van de gebeurtenis, zoals vermeld door get-events.','Get missing pages (404s)'=>'Ontbrekende pagina\'s (404\'s) ophalen','Paths that returned 404, ranked by hits. Split into broken links (reached from one of your own pages, with the page that links there, so they can be fixed) and probes (scanners and outside links). Use this for "do I have broken links" and for a 404 spike flagged by get-changes.'=>'Paden die een 404 gaven, gerangschikt op hits. Opgesplitst in kapotte links (bereikt vanaf een van je eigen pagina\'s, met de pagina die ernaar linkt, zodat ze kunnen worden gerepareerd) en probes (scanners en externe links). Gebruik dit voor "heb ik kapotte links" en voor een piek in 404\'s die get-changes heeft gemeld.','Get bot and crawler traffic'=>'Bot- en crawlerverkeer ophalen','Requests the bot filter rejected, per category (search engines, AI crawlers, SEO tools, monitors, scrapers and so on), with the share of all requests they made up. None of these are in the pageview totals; use this when numbers look lower than another tool\'s, or when asked how much AI crawlers read the site.'=>'Verzoeken die het botfilter heeft geweigerd, per categorie (zoekmachines, AI-crawlers, SEO-tools, monitors, scrapers enzovoort), met het aandeel van alle verzoeken dat ze uitmaakten. Geen van deze telt mee in de pageviewtotalen; gebruik dit als de cijfers lager lijken dan in een andere tool, of als iemand vraagt hoeveel AI-crawlers de site lezen.','Get Core Web Vitals'=>'Core Web Vitals ophalen','Core Web Vitals (LCP, INP, CLS) measured on real visitors, reported at the 75th percentile the way Google grades them, each with a good/needs-improvement/poor rating and the sample count. Empty when no measurements were recorded in the range.'=>'Core Web Vitals (LCP, INP, CLS) gemeten bij echte bezoekers, gerapporteerd op het 75e percentiel zoals Google ze beoordeelt, elk met een beoordeling goed/verbetering nodig/slecht en het aantal metingen. Leeg als er in de periode geen metingen zijn vastgelegd.','Get chart notes'=>'Grafiek­notities ophalen','Notes the site owner pinned to dates on the traffic chart, such as "newsletter sent" or "redesign launched". Check these when explaining a spike or a dip, since they often hold the reason.'=>'Notities die de site-eigenaar aan datums in de verkeersgrafiek heeft vastgepind, zoals "nieuwsbrief verstuurd" of "redesign gelanceerd". Bekijk ze als je een piek of een dip wilt verklaren, want vaak staat daar de reden in.','Get year in review'=>'Jaaroverzicht ophalen','The year in review for one calendar year: totals against the year before, the busiest month and day, the top pages, posts published that year, top referrers, countries, and AI crawler activity. Includes imported history from a previous analytics tool. Defaults to the current year.'=>'Het jaaroverzicht van één kalenderjaar: totalen t.o.v. het jaar ervoor, de drukste maand en dag, de populairste pagina\'s, in dat jaar gepubliceerde berichten, de belangrijkste verwijzers, landen en activiteit van AI-crawlers. Bevat geïmporteerde geschiedenis uit een eerdere analysetool. Standaard het huidige jaar.','The calendar year to report on. Defaults to the current year.'=>'Het kalenderjaar waarover je wilt rapporteren. Standaard het huidige jaar.','Get goal completions (Pro)'=>'Doelvoltooiingen ophalen (Pro)','Conversion goals with completion counts and total value for a date range. Requires Vireo Analytics Pro.'=>'Conversiedoelen met aantal voltooiingen en totale waarde voor een datumbereik. Vereist Vireo Analytics Pro.','Post not found.'=>'Bericht niet gevonden.','Goals feature unavailable.'=>'Doelfunctie niet beschikbaar.','Direct'=>'Direct','Search'=>'Zoeken','AI assistants'=>'AI-assistenten','Social'=>'Social','Referral'=>'Verwijzing','host must be a hostname or URL.'=>'host moet een hostnaam of URL zijn.','Google Search Console is not connected. Connect it under Vireo Analytics, Settings, Search Console & API.'=>'Google Search Console is niet gekoppeld. Koppel het via Vireo Analytics, Instellingen, Search Console & API.','name is required.'=>'name is verplicht.','year must be a calendar year with data, no later than the current year.'=>'year moet een kalenderjaar met gegevens zijn, niet later dan het huidige jaar.','Unknown ability.'=>'Onbekende ability.','Start date (YYYY-MM-DD). Defaults to 30 days ago.'=>'Startdatum (JJJJ-MM-DD). Standaard 30 dagen geleden.','End date (YYYY-MM-DD). Defaults to today.'=>'Einddatum (JJJJ-MM-DD). Standaard vandaag.','Maximum number of rows to return (1-100).'=>'Maximaal aantal rijen dat wordt teruggegeven (1-100).','pageviews today'=>'paginaweergaven vandaag','Pageviews today (Vireo Analytics)'=>'Paginaweergaven vandaag (Vireo Analytics)','Vireo Analytics is not recording.'=>'Vireo Analytics registreert niet.','%1$s. %2$d attempts have failed over the last %3$s. Visits are still being written to disk and will be counted once this clears.'=>'%1$s. De afgelopen %3$s zijn %2$d pogingen mislukt. Bezoeken worden nog steeds naar schijf weggeschreven en worden meegeteld zodra dit is opgelost.','Aggregation is failing'=>'Aggregatie mislukt','Pick a real date.'=>'Kies een geldige datum.','Add a short note to go with the date.'=>'Voeg een korte notitie toe bij deze datum.','Could not save that note.'=>'Deze notitie kon niet worden opgeslagen.','That site is no longer connected.'=>'Die site is niet meer gekoppeld.','You are not allowed to add notes.'=>'Je mag geen notities toevoegen.','You are not allowed to remove notes.'=>'Je mag geen notities verwijderen.','That note is already gone.'=>'Deze notitie bestaat al niet meer.','Forbidden.'=>'Verboden.','Failed to open output stream.'=>'Kon de uitvoerstroom niet openen.','AI crawlers'=>'AI-crawlers','Search engines'=>'Zoekmachines','SEO tools'=>'SEO-tools','Uptime monitors'=>'Uptime-monitors','Link previews'=>'Linkpreviews','Automated browsers'=>'Geautomatiseerde browsers','Scripts and clients'=>'Scripts en clients','Archivers and validators'=>'Archiveerders en validators','Prefetch and prerender'=>'Prefetch en prerender','Repeated views past the daily cap'=>'Herhaalde weergaven boven het daglimiet','Referrer spam'=>'Verwijzingsspam','Other bots'=>'Overige bots','%s comment'=>'%s reactie' . "\0" . '%s reacties','%s per 1,000 views'=>'%s per 1.000 weergaven','Traffic chart'=>'Verkeersgrafiek','What changed'=>'Wat er is veranderd','Top pages'=>'Toppagina\'s','Top referrers'=>'Belangrijkste verwijzingen','Top countries'=>'Belangrijkste landen','Technology'=>'Technologie','Pageviews today'=>'Paginaweergaven vandaag','Compared with yesterday up to the same time of day.'=>'Vergeleken met gisteren tot hetzelfde tijdstip van de dag.','Visitors today'=>'Bezoekers vandaag','Right now'=>'Nu','Last 14 days'=>'Laatste 14 dagen','Pageviews'=>'Paginaweergaven','Visitors'=>'Bezoekers','Pageviews, compared with the period before'=>'Paginaweergaven, vergeleken met de periode ervoor','7 days'=>'7 dagen','30 days'=>'30 dagen','90 days'=>'90 dagen','Top pages · last 7 days'=>'Toppagina\'s · laatste 7 dagen','Top referrers · last 7 days'=>'Belangrijkste verwijzingen · laatste 7 dagen','View full dashboard →'=>'Volledig dashboard bekijken →','No data yet.'=>'Nog geen gegevens.','Home'=>'Home','No traffic data yet.'=>'Nog geen verkeersgegevens.','%1$s: %2$s pageviews, %3$s visitors'=>'%1$s: %2$s paginaweergaven, %3$s bezoekers','Pageviews and visitors, last 14 days'=>'Paginaweergaven en bezoekers, laatste 14 dagen','Day'=>'Dag','Overview'=>'Overzicht','Search & AI'=>'Zoeken en AI','Page speed'=>'Paginasnelheid','Content'=>'Inhoud','Campaigns'=>'Campagnes','Issues'=>'Problemen','Starting…'=>'Bezig met starten…','Import complete.'=>'Import voltooid.','Something went wrong:'=>'Er is iets misgegaan:','Import cancelled.'=>'Import geannuleerd.','today'=>'vandaag','yesterday'=>'gisteren','last 7 days'=>'laatste 7 dagen','last 14 days'=>'laatste 14 dagen','last 30 days'=>'laatste 30 dagen','last 90 days'=>'laatste 90 dagen','this month'=>'deze maand','last month'=>'vorige maand','year to date'=>'dit jaar tot nu toe','Traffic overview · %s'=>'Verkeersoverzicht · %s','Traffic overview · %1$s – %2$s'=>'Verkeersoverzicht · %1$s – %2$s','(no path)'=>'(geen pad)','Unknown'=>'Onbekend','Desktop'=>'Desktop','Mobile'=>'Mobiel','Tablet'=>'Tablet','%s visitor vs the prior period'=>'%s bezoeker t.o.v. de vorige periode' . "\0" . '%s bezoekers t.o.v. de vorige periode','No prior-period data'=>'Geen gegevens van vorige periode','new'=>'nieuw','%1$s vs %2$s in the prior period'=>'%1$s ten opzichte van %2$s in de vorige periode','No prior period to compare against yet.'=>'Nog geen vorige periode om mee te vergelijken.','Pageviews are flat on the same period last year.'=>'Het aantal paginaweergaven is gelijk aan dezelfde periode vorig jaar.','Pageviews are flat on the prior period.'=>'Paginaweergaven zijn gelijk gebleven ten opzichte van de vorige periode.','Pageviews are up %d%%.'=>'Paginaweergaven zijn %d%% gestegen.','Pageviews are down %d%%.'=>'Paginaweergaven zijn %d%% gedaald.','Most of the drop is traffic that stopped coming from %s.'=>'De daling komt grotendeels doordat er geen verkeer meer van %s komt.','Most of the drop is %s.'=>'De daling komt grotendeels van %s.','Most of the rise is new traffic from %s.'=>'De stijging komt grotendeels door nieuw verkeer van %s.','Most of the rise is %s.'=>'De stijging komt grotendeels van %s.','%1$s took %2$s more of the mix.'=>'%1$s nam %2$s meer van de verdeling in.','%1$s lost %2$s of the mix.'=>'%1$s verloor %2$s van de verdeling.','No pageviews were recorded yesterday, but this site was busy the week before. Tracking may have stopped.'=>'Er zijn gisteren geen paginaweergaven vastgelegd, terwijl de site de week ervoor druk bezocht was. Mogelijk is het tracken gestopt.','Every visitor is being recorded as Unknown. Countries will stay empty until geo-location is set up.'=>'Elke bezoeker wordt vastgelegd als Onbekend. Landen blijven leeg totdat geolocatie is ingesteld.','404 errors are up %1$d%%, mostly on %2$s.'=>'404-fouten zijn %1$d%% gestegen, voornamelijk op %2$s.','Traffic is down %d%% on the prior period, well beyond normal variation.'=>'Het verkeer is %d%% gedaald ten opzichte van de vorige periode, veel meer dan normale schommelingen.','Traffic is up %d%% on the prior period, well beyond normal variation.'=>'Het verkeer is %d%% gestegen ten opzichte van de vorige periode, veel meer dan normale schommelingen.','Daily'=>'Dagelijks','Weekly'=>'Wekelijks','Monthly'=>'Maandelijks','month and yearF Y'=>'F Y','[%1$s] Daily Analytics: %2$s'=>'[%1$s] Dagelijkse analyse: %2$s','[%1$s] Monthly Analytics: %2$s'=>'[%1$s] Maandelijkse analyse: %2$s','[%1$s] Weekly Analytics: %2$s'=>'[%1$s] Wekelijkse analytics: %2$s','no views timed yet'=>'nog geen weergaven met tijdmeting','Time on page is recorded from this update on. A view reports its time when the reader leaves the page, and the next run of the collector records it, so the first figure appears within a few minutes of the first visit.'=>'De tijd op de pagina wordt vanaf deze update vastgelegd. Een weergave meldt de tijd zodra de lezer de pagina verlaat, en de volgende run van de collector legt die vast, dus het eerste cijfer verschijnt binnen enkele minuten na het eerste bezoek.','timed from %s'=>'gemeten vanaf %s','Time on page has been recorded since %s. This range ends before that, so there is nothing to average.'=>'De tijd op de pagina wordt vastgelegd sinds %s. Dit bereik eindigt daarvoor, dus er is niets om een gemiddelde van te berekenen.','no views timed in this range'=>'geen gemeten weergaven in dit bereik','Time on page has been recorded since %s, but no view in this range has reported a time yet. Views report when the reader leaves the page.'=>'De tijd op de pagina wordt vastgelegd sinds %s, maar geen enkele weergave in dit bereik heeft al een tijd gemeld. Weergaven melden zich zodra de lezer de pagina verlaat.','not counted yet'=>'nog niet geteld','Bounce rate starts counting once the update has finished setting up, on the next scheduled run or the next visit to wp-admin.'=>'Het bouncepercentage begint te tellen zodra de update klaar is met instellen, bij de volgende geplande run of het volgende bezoek aan wp-admin.','starts counting %s'=>'begint te tellen %s','Visitors who arrived before this update were already counted, so bounce rate starts with the first full day, %s.'=>'Bezoekers die vóór deze update binnenkwamen zijn al geteld, dus het bouncepercentage begint met de eerste volledige dag, %s.','counted from %s'=>'geteld vanaf %s','Bounce rate has been counted since %s. This range ends before that.'=>'Het bouncepercentage wordt geteld sinds %s. Dit bereik eindigt daarvoor.','counted from %s, no visitors yet'=>'geteld vanaf %s, nog geen bezoekers','Bounce rate has been counted since %s. It fills in with the first run of the collector after a visit, within a few minutes.'=>'Het bouncepercentage wordt geteld sinds %s. Het vult zich met de eerste run van de collector na een bezoek, binnen enkele minuten.','%ds'=>'%ds','%1$dm %2$02ds'=>'%1$dm %2$02ds','Event not found.'=>'Gebeurtenis niet gevonden.','Event · %s'=>'Gebeurtenis · %s','Support'=>'Ondersteuning','Rate Vireo'=>'Beoordeel Vireo','You do not have permission to do that.'=>'Je hebt hiervoor geen toestemming.','Hourly traffic is stored for the whole site, so the chart shows days while a filter is on.'=>'Verkeer per uur wordt voor de hele site opgeslagen, dus de grafiek toont dagen zolang er een filter actief is.','Referrers are only recorded per page for posts and pages with an ID, so this page can be filtered on its own but not combined with a source or referrer.'=>'Verwijzers worden alleen per pagina vastgelegd voor berichten en pagina\'s met een ID, dus deze pagina kan op zichzelf worden gefilterd, maar niet gecombineerd met een bron of verwijzer.','device'=>'apparaat','country'=>'land','source'=>'bron','referrer'=>'verwijzer','page'=>'pagina',', '=>', ','Vireo keeps daily totals per dimension, not per visit, so filtering by %s together cannot be answered exactly.'=>'Vireo bewaart dagtotalen per dimensie, niet per bezoek, dus filteren op %s samen kan niet exact worden beantwoord.','This breakdown is not stored by %s, so it is not shown while that filter is on.'=>'Deze uitsplitsing wordt niet bijgehouden door %s, dus ze wordt niet getoond zolang dat filter actief is.','The uploads directory is not writable, so the database cannot be saved.'=>'De uploadmap is niet beschrijfbaar, dus de database kan niet worden opgeslagen.','Could not download the database: %s'=>'Kon de database niet downloaden: %s','The downloaded database was empty.'=>'De gedownloade database was leeg.','The downloaded database could not be unpacked.'=>'De gedownloade database kon niet worden uitgepakt.','Could not create the database directory.'=>'Kon de databasemap niet aanmaken.','Could not write the database file.'=>'Kon het databasebestand niet wegschrijven.','That does not look like a service account key file. It should contain client_email and private_key.'=>'Dit lijkt geen serviceaccountsleutelbestand. Het moet client_email en private_key bevatten.','This server is missing the OpenSSL functions needed to authenticate with Google.'=>'Deze server mist de OpenSSL-functies die nodig zijn om bij Google te authenticeren.','Could not sign the request with that key. Check the key file was pasted whole.'=>'Het verzoek kon niet worden ondertekend met die sleutel. Controleer of het hele sleutelbestand is geplakt.','Google would not issue an access token for that key.'=>'Google wilde geen toegangstoken uitgeven voor die sleutel.','The job that records visits is not scheduled'=>'De taak die bezoeken registreert is niet ingepland','Visits are being written to disk but nothing is moving them into your reports. Deactivating and reactivating the plugin will restore it.'=>'Bezoeken worden naar schijf weggeschreven, maar niets verplaatst ze naar je rapporten. De plugin deactiveren en opnieuw activeren herstelt dit.','The recording job is scheduled'=>'De registratietaak is ingepland','WordPress cron is disabled on this site, which is normal on managed hosting: the host runs it externally instead. Recording depends on that continuing to run.'=>'WordPress-cron staat uit op deze site. Dat is normaal bij managed hosting: de host voert het dan extern uit. Registratie werkt alleen zolang dat blijft draaien.','Visits have not been recorded yet'=>'Er zijn nog geen bezoeken geregistreerd','This is expected on a new install. If it persists for more than a few minutes, the recording job is not running.'=>'Dit is normaal bij een nieuwe installatie. Duurt het langer dan een paar minuten, dan draait de registratietaak niet.','Visits stopped being recorded'=>'Bezoeken worden niet meer geregistreerd','The last successful run was %s ago, and it should run every minute. Anything since then is still on disk and will be counted once this clears.'=>'De laatste geslaagde run was %s geleden, terwijl deze elke minuut zou moeten draaien. Alles sindsdien staat nog op schijf en wordt meegeteld zodra dit is opgelost.','Visits are being recorded'=>'Bezoeken worden geregistreerd','Last run %s ago.'=>'Laatste run %s geleden.','The database is refusing writes'=>'De database weigert schrijfacties','%1$s. %2$d attempts have failed. The database reported: %3$s'=>'%1$s. %2$d pogingen zijn mislukt. De database meldde: %3$s','no detail recorded'=>'geen details geregistreerd','Some visits could not be saved'=>'Sommige bezoeken konden niet worden opgeslagen','%d batch was set aside after repeated database errors. The visits are still on disk and can be replayed once the cause is fixed.'=>'%d batch is opzijgezet na herhaalde databasefouten. De bezoeken staan nog op schijf en kunnen opnieuw worden verwerkt zodra de oorzaak is verholpen.' . "\0" . '%d batches zijn opzijgezet na herhaalde databasefouten. De bezoeken staan nog op schijf en kunnen opnieuw worden verwerkt zodra de oorzaak is verholpen.','Visits are piling up without being saved'=>'Bezoeken stapelen zich op zonder te worden opgeslagen','%1$s is waiting on disk, the oldest of it from %2$s ago. Visits are being captured but are not reaching your reports.'=>'%1$s staat te wachten op schijf, het oudste deel daarvan van %2$s geleden. Bezoeken worden vastgelegd maar bereiken je rapporten niet.','The data folder is missing'=>'De datamap ontbreekt','Visits cannot be captured at all until it can be created inside wp-content/uploads.'=>'Bezoeken kunnen pas worden vastgelegd zodra deze map kan worden aangemaakt binnen wp-content/uploads.','The data folder is not writable'=>'De datamap is niet beschrijfbaar','Visits are being discarded as they arrive. Check the folder permissions inside wp-content/uploads.'=>'Bezoeken worden weggegooid zodra ze binnenkomen. Controleer de mapmachtigingen binnen wp-content/uploads.','The data folder is writable'=>'De datamap is beschrijfbaar','The reporting tables are missing'=>'De rapportagetabellen ontbreken','Deactivating and reactivating the plugin will create them.'=>'De plugin deactiveren en opnieuw activeren maakt ze aan.','No visits recorded yet'=>'Nog geen bezoeken geregistreerd','Expected on a new install, or on a site with no traffic since the plugin was activated.'=>'Normaal bij een nieuwe installatie, of bij een site zonder verkeer sinds de plugin is geactiveerd.','Nothing has been recorded for a while'=>'Er is al een tijdje niets geregistreerd','The most recent day with any data is %s. On a site with regular traffic this means recording has stopped.'=>'De meest recente dag met gegevens is %s. Bij een site met regelmatig verkeer betekent dit dat de registratie is gestopt.','Reports are up to date'=>'Rapporten zijn actueel','Most recent data: %s.'=>'Meest recente gegevens: %s.','Vireo Analytics is recording visits'=>'Vireo Analytics registreert bezoeken','Analytics'=>'Analytics','The recording job is scheduled, ran recently, and your reports are up to date.'=>'De registratietaak is ingepland, is onlangs uitgevoerd en je rapporten zijn actueel.','Vireo Analytics has stopped recording visits'=>'Vireo Analytics registreert geen bezoeken meer','Vireo Analytics is recording, with something worth checking'=>'Vireo Analytics registreert, maar er is iets dat de moeite van het controleren waard is','Whether visits are currently being captured and written to the database.'=>'Of bezoeken op dit moment worden vastgelegd en naar de database worden weggeschreven.','“%1$s” gained the most, %2$s more view than the week before.'=>'‘%1$s’ groeide het meest, %2$s weergave meer dan de week ervoor.' . "\0" . '‘%1$s’ groeide het meest, %2$s weergaven meer dan de week ervoor.','%1$s sent visitors for the first time: %2$s views.'=>'%1$s heeft voor het eerst bezoekers gestuurd: %2$s weergaven.','Your best week so far: %1$s pageviews, ahead of the previous best of %2$s.'=>'Je beste week tot nu toe: %1$s paginaweergaven, meer dan de vorige topweek met %2$s.','The site passed %s pageviews in total.'=>'De site heeft in totaal %s paginaweergaven bereikt.','%1$s passed %2$s views.'=>'%1$s heeft %2$s weergaven bereikt.','%1$s was the busiest day, with %2$s view.'=>'%1$s was de drukste dag, met %2$s weergave.' . "\0" . '%1$s was de drukste dag, met %2$s weergaven.','Import from Koko Analytics'=>'Importeren uit Koko Analytics','Import from Jetpack Stats'=>'Importeren uit Jetpack Stats','Import from Google Analytics 4'=>'Importeren uit Google Analytics 4','Import from Plausible Analytics'=>'Importeren uit Plausible Analytics','Restore a Vireo Analytics backup'=>'Een Vireo Analytics-back-up herstellen','Import from %s'=>'Importeren uit %s','Unknown importer.'=>'Onbekende importfunctie.','Replacing deletes everything Vireo Analytics has recorded here before loading the file. Tick the box to confirm, or choose Merge.'=>'Vervangen wist alles wat Vireo Analytics hier heeft vastgelegd voordat het bestand wordt geladen. Vink het vakje aan om te bevestigen, of kies Samenvoegen.','Choose the backup file to begin.'=>'Kies het back-upbestand om te beginnen.','The saved key has been removed.'=>'De opgeslagen sleutel is verwijderd.','That key file could not be read. Paste the whole JSON file, including the private key.'=>'Dat sleutelbestand kon niet worden gelezen. Plak het hele JSON-bestand, inclusief de privésleutel.','Paste the service account key file to begin.'=>'Plak het serviceaccountsleutelbestand om te beginnen.','Enter the numeric GA4 property ID.'=>'Voer het numerieke GA4-property-ID in.','Choose a start date on or before the end date.'=>'Kies een startdatum op of vóór de einddatum.','You have already imported Google Analytics data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Je hebt al Google Analytics-gegevens geïmporteerd die %s dekken. Opnieuw importeren telt die cijfers op bij de reeds opgeslagen cijfers, en dat kan niet ongedaan worden gemaakt. Beperk de datums tot wat ontbreekt, of vink het vakje aan om toch te importeren.','Dates must be in YYYY-MM-DD format.'=>'Datums moeten in de indeling JJJJ-MM-DD staan.','Choose the export file from Plausible to begin.'=>'Kies het exportbestand van Plausible om te beginnen.','You have already imported Plausible data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Je hebt al Plausible-gegevens geïmporteerd voor %s. Als je ze opnieuw importeert, worden die aantallen opgeteld bij de aantallen die al zijn opgeslagen, en dat kan niet ongedaan worden gemaakt. Beperk de datums tot wat nog ontbreekt, of vink het selectievakje aan om toch te importeren.','All fields are required.'=>'Alle velden zijn verplicht.','Invalid Blog URI.'=>'Ongeldige blog-URI.','You have already imported Jetpack Stats covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Je hebt al Jetpack Stats-gegevens geïmporteerd voor %s. Als je ze opnieuw importeert, worden die aantallen opgeteld bij de aantallen die al zijn opgeslagen, en dat kan niet ongedaan worden gemaakt. Beperk de datums tot wat nog ontbreekt, of vink het selectievakje aan om toch te importeren.','This import screen is out of date. Reload it and start the import again.'=>'Dit importscherm is verouderd. Laad het opnieuw en start de import nogmaals.','%s has already been imported. Running it again would count the same history twice, so it needs confirming first. Reload the page to see what was imported.'=>'%s is al geïmporteerd. Als je de import opnieuw uitvoert, wordt dezelfde geschiedenis dubbel geteld, dus je moet dit eerst bevestigen. Laad de pagina opnieuw om te zien wat er is geïmporteerd.','Imported on %1$s at %2$s: %3$s day of history, %4$s to %5$s, %6$s pageviews.'=>'Geïmporteerd op %1$s om %2$s: %3$s dag aan geschiedenis, %4$s tot %5$s, %6$s paginaweergaven.' . "\0" . 'Geïmporteerd op %1$s om %2$s: %3$s dagen aan geschiedenis, %4$s tot %5$s, %6$s paginaweergaven.','Imported on %1$s at %2$s, covering %3$s to %4$s.'=>'Geïmporteerd op %1$s om %2$s, voor de periode %3$s tot %4$s.','Imported on %1$s at %2$s.'=>'Geïmporteerd op %1$s om %2$s.','everything available'=>'alles wat beschikbaar is','Collecting data. Your first pageviews appear within a minute; trends need a day to compare against.'=>'Gegevens worden verzameld. Je eerste paginaweergaven verschijnen binnen een minuut; voor trends is een dag nodig om mee te vergelijken.','Collecting data, %s view so far. Trends appear once there is a prior day to compare against.'=>'Gegevens verzamelen, tot nu toe %s weergave. Trends verschijnen zodra er een vorige dag is om mee te vergelijken.' . "\0" . 'Gegevens verzamelen, tot nu toe %s weergaven. Trends verschijnen zodra er een vorige dag is om mee te vergelijken.','%1$s Mostly %2$s.'=>'%1$s Vooral %2$s.','Steady, %1$s view, in line with the prior period. Top: %2$s.'=>'Stabiel, %1$s weergave, vergelijkbaar met de vorige periode. Top: %2$s.' . "\0" . 'Stabiel, %1$s weergaven, vergelijkbaar met de vorige periode. Top: %2$s.','Steady, %s view, in line with the prior period.'=>'Stabiel, %s weergave, vergelijkbaar met de vorige periode.' . "\0" . 'Stabiel, %s weergaven, vergelijkbaar met de vorige periode.','Source #%d'=>'Bron #%d','That tool cannot be run on a child site.'=>'Die tool kan niet op een onderliggende site worden uitgevoerd.','This site does not have that tool.'=>'Deze site heeft die tool niet.','Only read-only tools can be run on a child site.'=>'Op een onderliggende site kunnen alleen alleen-lezen tools worden uitgevoerd.','The tool input is too large.'=>'De invoer van de tool is te groot.','The tool input must be a JSON object.'=>'De invoer van de tool moet een JSON-object zijn.','Read-only site analytics: traffic, top content, where visitors came from, Google searches, AI assistant traffic, broken links, and what changed since the previous period.'=>'Alleen-lezen site-analyse: verkeer, populairste inhoud, waar bezoekers vandaan kwamen, Google-zoekopdrachten, verkeer van AI-assistenten, kapotte links en wat er sinds de vorige periode is veranderd.','Revenue, which pages and sources drive sales, campaigns, funnels and real-time visitors need Vireo Pro: https://vireowp.com/pricing/'=>'Omzet, welke pagina\'s en bronnen verkopen opleveren, campagnes, funnels en realtime bezoekers vereisen Vireo Pro: https://vireowp.com/pricing/','You do not have permission to access this page.'=>'Je hebt geen toestemming om deze pagina te openen.','That does not look like a Google API key. It is a single line of letters, numbers, dashes and underscores, usually starting with AIza.'=>'Dat lijkt niet op een Google API-sleutel. Een API-sleutel is één regel met letters, cijfers, streepjes en underscores en begint meestal met AIza.','That is not a page address PageSpeed can test.'=>'Dit is geen pagina-adres dat PageSpeed kan testen.','Only pages on this site can be tested.'=>'Alleen pagina\'s van deze site kunnen worden getest.','PageSpeed can only test pages anyone can open. Publish this post first.'=>'PageSpeed kan alleen pagina\'s testen die iedereen kan openen. Publiceer dit bericht eerst.','PageSpeed tests need a Google API key. An administrator can add one under Settings, Search Console & API.'=>'Voor PageSpeed-tests is een Google API-sleutel nodig. Een beheerder kan er een toevoegen onder Instellingen, Search Console & API.','A test of this page is already running. Its result shows here when it finishes.'=>'Er loopt al een test van deze pagina. Het resultaat verschijnt hier zodra de test klaar is.','Google did not answer within a minute. Slow pages can take that long. Try again.'=>'Google heeft niet binnen een minuut gereageerd. Trage pagina\'s kunnen zo lang duren. Probeer het opnieuw.','Could not reach Google: %s'=>'Google kon niet worden bereikt: %s','PageSpeed runs on Google\'s servers, which cannot reach a site that is only on your computer or private network.'=>'PageSpeed draait op de servers van Google, en die kunnen een site die alleen op je computer of in je privénetwerk staat niet bereiken.','Google\'s limit for PageSpeed tests on this API key is used up for now. Try again later, or raise the quota in Google Cloud.'=>'De limiet van Google voor PageSpeed-tests met deze API-sleutel is voorlopig bereikt. Probeer het later opnieuw of verhoog het quotum in Google Cloud.','Google rejected the API key. Check it under Settings, Search Console & API.'=>'Google heeft de API-sleutel geweigerd. Controleer de sleutel onder Instellingen, Search Console & API.','Google refused the request. Check that the PageSpeed Insights API is enabled in the key\'s Google Cloud project and that the key\'s restrictions allow it.'=>'Google heeft het verzoek geweigerd. Controleer of de PageSpeed Insights API is ingeschakeld in het Google Cloud-project van de sleutel en of de beperkingen van de sleutel dit toestaan.','Google\'s test could not load this page. Check that it is public and opens for logged-out visitors.'=>'De test van Google kon deze pagina niet laden. Controleer of de pagina openbaar is en ook opent voor bezoekers die niet zijn ingelogd.','PageSpeed Insights sent back a result this version of Vireo cannot read.'=>'PageSpeed Insights heeft een resultaat teruggestuurd dat deze versie van Vireo niet kan lezen.','PageSpeed Insights returned an error (HTTP %d). Try again in a few minutes.'=>'PageSpeed Insights gaf een fout terug (HTTP %d). Probeer het over een paar minuten opnieuw.','Blocking time'=>'Blokkeertijd','First content'=>'Eerste inhoud','The lab stand-in for response to clicks. A test cannot click, so it measures how long the page was too busy to respond.'=>'De labtest-vervanger voor de reactie op klikken. Een test kan niet klikken, dus meet hij hoe lang de pagina te druk was om te reageren.','How long until anything appeared.'=>'Hoe lang het duurde voordat er iets verscheen.','Up to %s faster'=>'Tot %s sneller','Less layout shift'=>'Minder layoutverschuiving','You are not allowed to run page tests.'=>'Je mag geen paginatests uitvoeren.','Popular posts (Vireo)'=>'Populaire berichten (Vireo)','Your most viewed posts, from Vireo Analytics.'=>'Je meest bekeken berichten, van Vireo Analytics.','Popular posts'=>'Populaire berichten','Last 7 days'=>'Laatste 7 dagen','Last 30 days'=>'Laatste 30 dagen','Last 90 days'=>'Laatste 90 dagen','All time'=>'Alle tijd','Title:'=>'Titel:','Number of posts:'=>'Aantal berichten:','Period:'=>'Periode:','Post types:'=>'Berichttypen:','Display:'=>'Weergave:','List'=>'Lijst','List with featured images'=>'Lijst met uitgelichte afbeeldingen','Show view counts'=>'Aantal weergaven tonen','Leave out the post being viewed'=>'Het bericht dat wordt bekeken weglaten','%s view'=>'%s weergave' . "\0" . '%s weergaven','No popular posts yet. They appear here once Vireo has recorded views for published posts in this period.'=>'Nog geen populaire berichten. Ze verschijnen hier zodra Vireo weergaven van gepubliceerde berichten in deze periode heeft geregistreerd.','Views (30d)'=>'Weergaven (30d)','%s in 30 days'=>'%s in 30 dagen','Post stats · %s'=>'Berichtstatistieken · %s','Referrer not specified.'=>'Geen verwijzing opgegeven.','Referrer · %s'=>'Verwijzing · %s','Invalid start or end date.'=>'Ongeldige start- of einddatum.','end must be on or after start.'=>'einde moet op of na start liggen.','Goal not found.'=>'Doel niet gevonden.','180 days'=>'180 dagen','1 year'=>'1 jaar','2 years'=>'2 jaar','5 years'=>'5 jaar','Never purge'=>'Nooit opschonen','Give the view a name.'=>'Geef de weergave een naam.','You can keep up to %d saved views. Delete one to save another.'=>'Je kunt maximaal %d opgeslagen weergaven bewaren. Verwijder er een om een nieuwe op te slaan.','Enter the property exactly as Search Console shows it, either a URL or sc-domain:example.com.'=>'Voer de property exact in zoals Search Console die toont, als URL of als sc-domain:example.com.','Search Console is not connected yet.'=>'Search Console is nog niet gekoppeld.','Could not store the data for %s. Nothing was lost; run the sync again.'=>'De gegevens voor %s konden niet worden opgeslagen. Er is niets verloren gegaan; voer de synchronisatie opnieuw uit.','Google refused the request. Check the service account has access to this Search Console property.'=>'Google heeft het verzoek geweigerd. Controleer of het serviceaccount toegang heeft tot deze Search Console-property.','Search Console has no property with that address. Copy it exactly as it appears there.'=>'Search Console heeft geen property met dat adres. Kopieer het exact zoals het daar staat.','Search Console returned an unexpected response (HTTP %d).'=>'Search Console gaf een onverwachte reactie (HTTP %d).','Search Console returned a response we could not read.'=>'Search Console gaf een reactie die we niet konden lezen.','General'=>'Algemeen','Tracking'=>'Tracking','Email digest'=>'E-mailoverzicht','Search Console & API'=>'Search Console en API','Import & export'=>'Importeren en exporteren','Vireo Analytics Settings'=>'Vireo Analytics-instellingen','Settings'=>'Instellingen','Settings saved.'=>'Instellingen opgeslagen.','Vireo Analytics:'=>'Vireo Analytics:','Geo-location database is missing. Countries will show as unknown until you install it.'=>'De geolocatiedatabase ontbreekt. Landen worden weergegeven als onbekend totdat je deze installeert.','Setup instructions'=>'Installatie-instructies','Nothing was removed. Type the site\'s name exactly as shown to confirm.'=>'Er is niets verwijderd. Typ de naam van de site precies zoals weergegeven om te bevestigen.','Filtered as bot.'=>'Gefilterd als bot.','Empty User-Agent is treated as a bot by Bot_Filter::is_bot_request.'=>'Een lege User-Agent wordt door Bot_Filter::is_bot_request als bot behandeld.','Filtered as bot. This request would NOT be tracked.'=>'Gefilterd als bot. Dit verzoek zou NIET worden getrackt.','Would be tracked. This request passes the bot filter.'=>'Wordt getrackt. Dit verzoek komt door het botfilter.','Matched the bot-UA pattern: %s'=>'Kwam overeen met het bot-UA-patroon: %s','Matched via heuristic (e.g. empty UA) rather than the UA regex.'=>'Herkend via een heuristiek (bijv. een lege UA) in plaats van de UA-regex.','No bot-UA pattern matched, and no Cloudflare bot signals would fire for a typical request.'=>'Er kwam geen bot-UA-patroon overeen en er zouden voor een normaal verzoek geen Cloudflare-botsignalen afgaan.','The front-end address was not saved. Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Het front-endadres is niet opgeslagen. Voer het volledige adres van de site in, beginnend met http:// of https://, bijvoorbeeld https://www.example.com.','Give the site a name.'=>'Geef de site een naam.','Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Voer het volledige adres van de site in, beginnend met http:// of https://, bijvoorbeeld https://www.example.com.','This install has reached its number of connected sites.'=>'Deze installatie heeft het maximale aantal gekoppelde sites bereikt.','That address is already connected.'=>'Dat adres is al gekoppeld.','That address is set as the headless front end. A site is either the front end for this WordPress site or a connected site with its own numbers, not both.'=>'Dat adres is ingesteld als de headless front-end. Een site is óf de front-end van deze WordPress-site óf een gekoppelde site met eigen cijfers, niet allebei.','That is this site\'s own address. Its pages are already counted.'=>'Dat is het eigen adres van deze site. De pagina\'s worden al meegeteld.','%ss'=>'%ss','%sms'=>'%sms','Load time'=>'Laadtijd','Response to clicks'=>'Reactie op klikken','Layout shift'=>'Lay-outverschuiving','Good'=>'Goed','Needs work'=>'Kan beter','Poor'=>'Slecht','How long until the main content appeared.'=>'Hoe lang het duurde voordat de hoofdinhoud verscheen.','How long the page took to respond when someone interacted with it.'=>'Hoe lang de pagina erover deed om te reageren toen iemand ermee interactie had.','How much the page moved around while it loaded.'=>'Hoeveel de pagina verschoof tijdens het laden.','%1$s to %2$s'=>'%1$s tot %2$s','%1$s: imported from %2$s.'=>'%1$s: geïmporteerd uit %2$s.','%1$s: partly imported from %2$s, partly counted by Vireo Analytics.'=>'%1$s: deels geïmporteerd uit %2$s, deels geteld door Vireo Analytics.','%s: counted by Vireo Analytics.'=>'%s: geteld door Vireo Analytics.','%1$s in %2$s so far'=>'%1$s in %2$s tot nu toe','%1$s in %2$s'=>'%1$s in %2$s','%s pageview.'=>'%s paginaweergave.' . "\0" . '%s paginaweergaven.','%1$s pageviews, %2$s on the same stretch of %3$s.'=>'%1$s paginaweergaven, %2$s in dezelfde periode van %3$s.','%1$s pageviews, %2$s on %3$s.'=>'%1$s paginaweergaven, %2$s in %3$s.','Busiest month: %1$s. Busiest day: %2$s, with %3$s pageviews.'=>'Drukste maand: %1$s. Drukste dag: %2$s, met %3$s paginaweergaven.','Top page: %1$s (%2$s pageviews).'=>'Toppagina: %1$s (%2$s paginaweergaven).','Top referrer: %1$s (%2$s pageviews).'=>'Belangrijkste verwijzer: %1$s (%2$s paginaweergaven).','Top country: %s.'=>'Belangrijkste land: %s.','Includes history imported from %s.'=>'Bevat geschiedenis die is geïmporteerd uit %s.','Home page and archives (imported)'=>'Startpagina en archieven (geïmporteerd)','Google app'=>'Google-app','short date with yearM j, Y'=>'j M Y','short date without yearM j'=>'j M','Today'=>'Vandaag','Yesterday'=>'Gisteren','Last 7'=>'Laatste 7','Last 14'=>'Laatste 14','Last 30'=>'Laatste 30','Last 90'=>'Laatste 90','This month'=>'Deze maand','Last month'=>'Vorige maand','YTD'=>'Dit jaar','Not shown with these filters'=>'Niet getoond met deze filters','Previous period'=>'Vorige periode','Same period last year'=>'Dezelfde periode vorig jaar','Device is %s'=>'Apparaat is %s','Country is %s'=>'Land is %s','Source is %s'=>'Bron is %s','Referrer is %s'=>'Verwijzer is %s','Page is %s'=>'Pagina is %s','Vireo keeps daily totals per dimension, so this cannot be combined with the filters already on.'=>'Vireo houdt dagtotalen per dimensie bij, dus dit kan niet worden gecombineerd met de filters die al actief zijn.','Site'=>'Site','This site'=>'Deze site','Switch'=>'Wisselen','This link asked for a view that has expired, so the default range is shown instead. Dashboard links stop working after about a day. Pick a range below to carry on.'=>'Deze link vroeg om een weergave die is verlopen, dus wordt in plaats daarvan het standaardbereik getoond. Dashboardlinks werken na ongeveer een dag niet meer. Kies hieronder een bereik om verder te gaan.','All devices'=>'Alle apparaten','All sources'=>'Alle bronnen','All countries'=>'Alle landen','Filter:'=>'Filter:','Device'=>'Apparaat','Country'=>'Land','Source'=>'Bron','Apply'=>'Toepassen','Remove this filter'=>'Dit filter verwijderen','Clear all'=>'Alles wissen','Saved views'=>'Opgeslagen weergaven','Saved views…'=>'Opgeslagen weergaven…','Forget view'=>'Weergave vergeten','Save view'=>'Weergave opslaan','View name'=>'Naam van weergave','Name this view'=>'Geef deze weergave een naam','Save'=>'Opslaan','Cancel'=>'Annuleren','Clear the filters'=>'Filters wissen','Filters apply to the Overview tab.'=>'Filters zijn van toepassing op het tabblad Overzicht.','Date range'=>'Datumbereik','Custom'=>'Aangepast','Year in review'=>'Jaaroverzicht','Print / Save as PDF'=>'Afdrukken / Opslaan als pdf','Compare'=>'Vergelijken','Compare with'=>'Vergelijken met','Start'=>'Start','End'=>'Einde','Move %s. Drag, or focus and use the arrow keys.'=>'%s verplaatsen. Sleep, of focus en gebruik de pijltjestoetsen.','Reset layout'=>'Indeling terugzetten','Report sections'=>'Rapportsecties','Loading the backup of %1$s, %2$s to %3$s, %4$s rows. %5$s'=>'De back-up van %1$s wordt geladen, %2$s tot %3$s, %4$s rijen. %5$s','Everything recorded here is deleted first.'=>'Alles wat hier is vastgelegd, wordt eerst verwijderd.','Days in the file replace the same days here; everything else is kept.'=>'Dagen in het bestand vervangen dezelfde dagen hier; al het andere blijft behouden.','Loads a file made with Download backup on another install, or on this one. Everything the reports are built from comes across: daily totals, pages, referrers, countries, devices, events, missing pages, bot traffic, Core Web Vitals, chart notes and the Search Console cache. Settings and connected sites are not in the file.'=>'Laadt een bestand dat is gemaakt met Back-up downloaden op een andere installatie, of op deze. Alles waarmee de rapporten worden opgebouwd komt mee: dagtotalen, pagina\'s, verwijzers, landen, apparaten, gebeurtenissen, ontbrekende pagina\'s, botverkeer, Core Web Vitals, grafieknotities en de Search Console-cache. Instellingen en gekoppelde sites zitten niet in het bestand.','To make the file, open %s on the site you are copying from and use Download backup.'=>'Om het bestand te maken open je %s op de site waarvan je kopieert en gebruik je Back-up downloaden.','Settings, Import & export'=>'Instellingen, Importeren en exporteren','Backup file (.jsonl.gz or .jsonl)'=>'Back-upbestand (.jsonl.gz of .jsonl)','Maximum upload size: %s.'=>'Maximale uploadgrootte: %s.','What to do with the numbers already here'=>'Wat je wilt doen met de cijfers die hier al staan','Merge: days in the file replace the same days here, everything else is kept.'=>'Samenvoegen: dagen in het bestand vervangen dezelfde dagen hier, al het andere blijft behouden.','Replace: delete everything recorded here first, so this site ends up holding exactly what the file holds.'=>'Vervangen: eerst alles verwijderen wat hier is vastgelegd, zodat deze site precies bevat wat het bestand bevat.','Replace deletes every report table on this site before loading the file, and that cannot be undone. Download a backup of this site first if there is anything here you might want back.'=>'Vervangen verwijdert alle rapporttabellen op deze site voordat het bestand wordt geladen, en dat kun je niet ongedaan maken. Download eerst een back-up van deze site als je hier iets wilt kunnen terughalen.','I understand that everything recorded here will be deleted.'=>'Ik begrijp dat alles wat hier is vastgelegd, wordt verwijderd.','Loading the same file twice gives the same numbers, so a restore that stopped partway can simply be run again.'=>'Hetzelfde bestand twee keer laden geeft dezelfde cijfers, dus een herstelactie die halverwege is gestopt, kun je gewoon opnieuw uitvoeren.','Earlier restores'=>'Eerdere herstelacties','Restore'=>'Herstellen','Restore progress'=>'Voortgang van herstel','View your reports'=>'Bekijk je rapporten','%s history imported'=>'%s-geschiedenis geïmporteerd','It is part of your Vireo Analytics reports now. Imports cannot be undone, and running this one again would add the same history a second time.'=>'Het maakt nu deel uit van je Vireo Analytics-rapporten. Imports kunnen niet ongedaan worden gemaakt, en als je deze opnieuw uitvoert, wordt dezelfde geschiedenis een tweede keer toegevoegd.','Go to Plugins'=>'Naar Plugins','This server is missing the OpenSSL functions needed to authenticate with Google. Ask your host to enable the PHP openssl extension.'=>'Deze server mist de OpenSSL-functies die nodig zijn om bij Google te authenticeren. Vraag je host om de PHP openssl-extensie in te schakelen.','Brings across daily pageviews and visitors, your pages, referrers, which pages each referrer sent readers to, countries, devices, outbound clicks, downloads, form submissions and your own custom events. Everything is stored in your own database, the same as traffic recorded from here on.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, plus je pagina\'s, verwijzers, naar welke pagina\'s elke verwijzer lezers heeft gestuurd, landen, apparaten, uitgaande klikken, downloads, formulierinzendingen en je eigen aangepaste gebeurtenissen. Alles wordt opgeslagen in je eigen database, net als het verkeer dat vanaf nu wordt geregistreerd.','How to get the key file'=>'Hoe je het sleutelbestand krijgt','In Google Cloud Console'=>'In Google Cloud Console','Create a project, or open one you already have.'=>'Maak een project aan, of open een project dat je al hebt.','Under APIs and services, enable the Google Analytics Data API. The plain Analytics API is a different one and will not work.'=>'Schakel onder API\'s en services de Google Analytics Data API in. De gewone Analytics API is een andere en werkt niet.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com, and you need that address for the next part.'=>'Maak onder IAM en beheer, dan Serviceaccounts, een serviceaccount aan. Het adres eindigt op .iam.gserviceaccount.com, en dat adres heb je nodig voor het volgende onderdeel.','Open the service account, go to Keys, add a key, and choose JSON. The file downloads once and Google will not give it to you again.'=>'Open het serviceaccount, ga naar Sleutels, voeg een sleutel toe en kies JSON. Het bestand wordt eenmalig gedownload en Google geeft het je niet nog eens.','In Google Analytics'=>'In Google Analytics','Open Admin, then Property access management, and add the service account address with Viewer access. Grant it on the property you want to import, not on the account.'=>'Open Beheerder, dan Toegangsbeheer voor property, en voeg het serviceaccountadres toe met Kijker-toegang. Verleen dit op de property die je wilt importeren, niet op het account.','Your property ID is the number under Admin, then Property details. It is digits only, not the G- measurement ID.'=>'Je property-ID is het nummer onder Beheerder, dan Property-details. Het bestaat alleen uit cijfers, niet het G-metings-ID.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below. The key stays in your database and is only used to ask Google for your own data. It is never sent anywhere else.'=>'Open daarna het gedownloade bestand in een teksteditor en plak het geheel, inclusief accolades, in het vak hieronder. De sleutel blijft in je database en wordt alleen gebruikt om Google om je eigen gegevens te vragen. Hij wordt nooit ergens anders naartoe gestuurd.','Service account key (JSON)'=>'Serviceaccountsleutel (JSON)','A key is saved. Leave this empty to keep it.'=>'Er is een sleutel opgeslagen. Laat dit leeg om die te behouden.','Using %s. Grant that address Viewer access on the property.'=>'Gebruikt %s. Verleen dat adres Kijker-toegang op de property.','Property ID'=>'Property-ID','Start date'=>'Startdatum','End date'=>'Einddatum','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, narrow the range to what is missing rather than starting again from the beginning.'=>'Dezelfde datums twee keer importeren telt de cijfers twee keer op, en dat kan niet ongedaan worden gemaakt. Stopt een run halverwege, beperk dan de periode tot wat ontbreekt in plaats van opnieuw vanaf het begin te starten.','Already imported'=>'Al geïmporteerd','Import these dates again anyway, adding to what is already stored.'=>'Importeer deze datums toch opnieuw, toegevoegd aan wat al is opgeslagen.','Start import'=>'Import starten','Import progress'=>'Importvoortgang','Remove the saved key'=>'Opgeslagen sleutel verwijderen','The key is only needed while importing. Removing it does not affect data already brought across.'=>'De sleutel is alleen nodig tijdens het importeren. Verwijderen heeft geen invloed op gegevens die al zijn binnengehaald.','No %s data found in this database. The plugin needs to have been installed on this site and collected some data before there is anything to bring across.'=>'Geen %s-gegevens gevonden in deze database. De plugin moet op deze site geïnstalleerd zijn geweest en gegevens hebben verzameld voordat er iets over te zetten valt.','Back to import & export'=>'Terug naar Importeren en exporteren','Records found'=>'Gevonden records','What this does:'=>'Wat dit doet:','Copies your history from %s into Vireo Analytics. The source data is read only and is never modified.'=>'Kopieert je geschiedenis uit %s naar Vireo Analytics. De brongegevens worden alleen gelezen en nooit gewijzigd.','Run it once.'=>'Voer het één keer uit.','An import adds what it reads to what Vireo Analytics already holds, so a second run would count the same history twice. Imports cannot be undone.'=>'Een import voegt wat hij leest toe aan wat Vireo Analytics al bevat, dus een tweede run telt dezelfde geschiedenis dubbel. Imports kunnen niet ongedaan worden gemaakt.','Import again anyway'=>'Toch opnieuw importeren','Only if Vireo Analytics no longer holds the history from %s, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Alleen als Vireo Analytics de geschiedenis van %s niet meer bevat, bijvoorbeeld nadat de gegevens zijn gereset. Anders wordt elke hierboven geïmporteerde dag dubbel geteld, en kun je dat niet meer terugdraaien.','I understand this adds the same history a second time.'=>'Ik begrijp dat dit dezelfde geschiedenis een tweede keer toevoegt.','Import again'=>'Opnieuw importeren','You can deactivate %s whenever you are ready. Vireo Analytics is tracking on its own now.'=>'Je kunt %s nu deactiveren. Vireo Analytics houdt zelf alles bij.','Jetpack isn\'t active here, so the import uses your WordPress.com API key.'=>'Jetpack is hier niet actief, dus de import gebruikt je WordPress.com API-sleutel.','Pulls daily pageviews and referrers from the Jetpack / WordPress.com stats API. Country and device data isn\'t available in this API — Vireo Analytics will start tracking those from installation onward.'=>'Haalt dagelijkse paginaweergaven en verwijzingen op via de Jetpack-/WordPress.com-stats-API. Land- en apparaatgegevens zijn niet beschikbaar in deze API; Vireo Analytics begint die vanaf de installatie bij te houden.','Jetpack Stats has no visitor counts, so imported days show pageviews only.'=>'Jetpack Stats heeft geen bezoekersaantallen, dus geïmporteerde dagen tonen alleen paginaweergaven.','WordPress.com API key'=>'WordPress.com-API-sleutel','A key is saved for this import — leave blank to reuse it'=>'Er is een sleutel opgeslagen voor deze import; laat leeg om deze opnieuw te gebruiken','Find this under <strong>Jetpack → Settings → Security → Akismet</strong>, or in your WordPress.com account under <strong>Security → Application Passwords</strong>.'=>'Deze vind je onder <strong>Jetpack → Instellingen → Beveiliging → Akismet</strong>, of in je WordPress.com-account onder <strong>Beveiliging → Applicatiewachtwoorden</strong>.','Blog URI'=>'Blog-URI','The domain Jetpack is tracking. Usually your site\'s host.'=>'Het domein dat Jetpack bijhoudt. Meestal de host van je site.','Re-running is additive.'=>'Opnieuw uitvoeren voegt gegevens toe.','Running the import over an overlapping date range will double-count those days.'=>'Als je de import over een overlappend datumbereik uitvoert, worden die dagen dubbel geteld.','No Koko Analytics data found in this database. If you just activated Koko Analytics, let it collect some pageviews first and come back.'=>'Geen Koko Analytics-gegevens gevonden in deze database. Als je Koko Analytics net hebt geactiveerd, laat het dan eerst wat paginaweergaven verzamelen en kom later terug.','Days of data'=>'Dagen aan gegevens','Copies Koko\'s daily rollups into Vireo Analytics\'s tables. Koko\'s data is not modified.'=>'Kopieert de dagelijkse samenvattingen van Koko naar de tabellen van Vireo Analytics. De gegevens van Koko worden niet gewijzigd.','Pageviews, visitors, pages and referrers come across. Countries, devices and events from Koko Analytics Pro are not imported.'=>'Paginaweergaven, bezoekers, pagina\'s en verwijzers worden overgenomen. Landen, apparaten en gebeurtenissen uit Koko Analytics Pro worden niet geïmporteerd.','Only if Vireo Analytics no longer holds the history from Koko Analytics, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Alleen als Vireo Analytics de geschiedenis van Koko Analytics niet meer bevat, bijvoorbeeld nadat de gegevens zijn gereset. Anders wordt elke hierboven geïmporteerde dag dubbel geteld, en kun je dat niet meer terugdraaien.','You can deactivate Koko Analytics from the Plugins screen when you\'re ready. Vireo Analytics is tracking on its own now.'=>'Je kunt Koko Analytics deactiveren via het scherm Plugins. Vireo Analytics houdt zelf alles bij.','Dismiss'=>'Sluiten','Welcome to Vireo Analytics.'=>'Welkom bij Vireo Analytics.','We found Koko Analytics here with %d day of data. Bring it across in one click, rather than starting at zero.'=>'We hebben hier Koko Analytics gevonden met %d dag aan gegevens. Neem ze met één klik over, in plaats van helemaal opnieuw te beginnen.' . "\0" . 'We hebben hier Koko Analytics gevonden met %d dagen aan gegevens. Neem ze met één klik over, in plaats van helemaal opnieuw te beginnen.','We found %s on this site. Import that history so your numbers do not start at zero. Your existing data is read only and is never changed.'=>'We hebben %s op deze site gevonden. Importeer die geschiedenis zodat je cijfers niet bij nul beginnen. Je bestaande gegevens worden alleen gelezen en nooit gewijzigd.','Start fresh'=>'Opnieuw beginnen','Vireo Analytics has its own data from %1$s, so the import stops on %2$s. Days from %1$s on keep the counts Vireo recorded.'=>'Vireo Analytics heeft eigen gegevens vanaf %1$s, dus de import stopt op %2$s. Voor dagen vanaf %1$s blijven de aantallen staan die Vireo heeft vastgelegd.','Also import %s onwards. Those days already hold what Vireo counted, so the imported numbers are added on top and the days are counted twice.'=>'Importeer ook alles vanaf %s. Die dagen bevatten al wat Vireo heeft geteld, dus de geïmporteerde cijfers worden erbovenop opgeteld en de dagen worden dubbel geteld.','daily visitors and pageviews'=>'dagelijkse bezoekers en paginaweergaven','device types'=>'apparaattypen','entry pages'=>'instappagina\'s','exit pages'=>'uitstappagina\'s','browsers'=>'browsers','operating systems'=>'besturingssystemen','goals and custom events'=>'doelen en aangepaste gebeurtenissen','custom properties'=>'aangepaste properties','referrers, which this export names without their addresses'=>'verwijzingen, die in deze export zonder hun adressen staan','Importing %1$s to %2$s: %3$s.'=>'%1$s tot %2$s importeren: %3$s.','Not imported, because Vireo Analytics has nowhere to keep them: %s.'=>'Niet geïmporteerd, omdat Vireo Analytics geen plek heeft om ze op te slaan: %s.','Import another export'=>'Nog een export importeren','For an export covering dates not imported yet. Dates already imported are refused unless you confirm them below.'=>'Voor een export met datums die nog niet zijn geïmporteerd. Datums die al zijn geïmporteerd worden geweigerd, tenzij je ze hieronder bevestigt.','Brings across daily pageviews and visitors, your pages, referrers, countries, device types, and goals and custom events from a Plausible export. Outbound link clicks, file downloads and form submissions become the same events Vireo Analytics records itself, and 404 events are listed under missing pages. Browsers and operating systems are not imported: Plausible exports them separately from device type, and Vireo Analytics stores the three together, so for imported days they show as Unknown.'=>'Neemt dagelijkse paginaweergaven en bezoekers over, plus je pagina\'s, verwijzers, landen, apparaattypen en doelen en aangepaste gebeurtenissen uit een Plausible-export. Klikken op uitgaande links, bestandsdownloads en formulierinzendingen worden dezelfde gebeurtenissen als die Vireo Analytics zelf registreert, en 404-gebeurtenissen staan onder ontbrekende pagina\'s. Browsers en besturingssystemen worden niet geïmporteerd: Plausible exporteert ze apart van het apparaattype, terwijl Vireo Analytics ze alle drie samen opslaat, dus voor geïmporteerde dagen worden ze weergegeven als Onbekend.','How to get the export'=>'Zo haal je de export op','In Plausible, open the site, then Site settings, then Imports & Exports.'=>'Open in Plausible de site, dan Site settings en vervolgens Imports & Exports.','Under Export data, start an export. Plausible emails a link to a zip file when it is ready.'=>'Start onder Export data een export. Plausible mailt een link naar een zipbestand zodra het klaar is.','Download the zip and upload it here as it is. If you have already unzipped it, select the CSV files instead.'=>'Download de zip en upload hem hier zoals hij is. Heb je hem al uitgepakt, selecteer dan de CSV-bestanden.','The file is read once and deleted. Nothing is sent to Plausible and no account details are needed.'=>'Het bestand wordt één keer gelezen en daarna verwijderd. Er wordt niets naar Plausible verstuurd en je hoeft geen accountgegevens in te voeren.','Plausible export (.zip or .csv files)'=>'Plausible-export (.zip- of .csv-bestanden)','Optional. Leave both empty to import every day in the export.'=>'Optioneel. Laat beide leeg om elke dag in de export te importeren.','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, set the dates to what is missing rather than starting again from the beginning.'=>'Als je dezelfde datums twee keer importeert, worden de cijfers twee keer opgeteld en dat kun je niet ongedaan maken. Als een import halverwege stopt, stel dan de datums in op wat nog ontbreekt in plaats van helemaal opnieuw te beginnen.','Analytics across the network'=>'Analytics binnen het netwerk','Last %d day'=>'Laatste %d dag' . "\0" . 'Laatste %d dagen','Refresh'=>'Vernieuwen','This network has more sites than one page can query. Showing the first %1$s of %2$s.'=>'Dit netwerk heeft meer sites dan één pagina kan opvragen. De eerste %1$s van %2$s worden getoond.','No site on the network has recorded anything yet.'=>'Nog geen enkele site in het netwerk heeft iets geregistreerd.','%1$s and %2$s across %3$s, %4$s to %5$s.'=>'%1$s en %2$s over %3$s, %4$s tot %5$s.','%s pageview'=>'%s paginaweergave' . "\0" . '%s paginaweergaven','%s visitor'=>'%s bezoeker' . "\0" . '%s bezoekers','%s site'=>'%s site' . "\0" . '%s sites','Open'=>'Openen','Totals are cached for fifteen minutes, since each one is a separate query against that site.'=>'Totalen worden vijftien minuten gecachet, omdat elk totaal een aparte query op die site is.','Monday'=>'Maandag','Tuesday'=>'Dinsdag','Wednesday'=>'Woensdag','Thursday'=>'Donderdag','Friday'=>'Vrijdag','Saturday'=>'Zaterdag','Sunday'=>'Zondag','WordPress handed the test email for %s to your server\'s mail system.'=>'WordPress heeft de testmail voor %s doorgegeven aan het mailsysteem van je server.','If it has not arrived within a few minutes, check your spam folder. If it is not there either, your host is not delivering mail sent from WordPress, which affects password resets and every other email the site sends. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Is hij na een paar minuten nog niet binnen, kijk dan in je spammap. Staat hij daar ook niet, dan bezorgt je host geen mail die vanuit WordPress wordt verstuurd. Dat geldt ook voor wachtwoordherstel en elke andere mail van de site. Een SMTP-plugin zoals WP Mail SMTP of FluentSMTP lost dat meestal op.','WordPress could not send the test email to %s.'=>'WordPress kon de testmail naar %s niet verzenden.','The mail system said: %s'=>'Het mailsysteem meldde: %s','This is a problem with how the site sends mail, not with the digest. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Dit is een probleem met hoe de site mail verstuurt, niet met het overzicht. Een SMTP-plugin zoals WP Mail SMTP of FluentSMTP lost dat meestal op.','Email reports class is not loaded.'=>'De klasse voor e-mailrapporten is niet geladen.','Country database installed. Countries will resolve from now on.'=>'Landendatabase geïnstalleerd. Landen worden vanaf nu herleid.','The country database could not be installed.'=>'De landendatabase kon niet worden geïnstalleerd.','Site connected. Paste its tag into the site and its visits will start showing on the dashboard.'=>'Site gekoppeld. Plak de tag in de site en de bezoeken verschijnen daarna op het dashboard.','Site removed, along with everything recorded for it.'=>'Site verwijderd, samen met alles wat ervoor is vastgelegd.','That did not work.'=>'Dat is niet gelukt.','%s stored day removed from the countries report.'=>'%s opgeslagen dag verwijderd uit het landenrapport.' . "\0" . '%s opgeslagen dagen verwijderd uit het landenrapport.','Settings sections'=>'Instellingensecties','Do not count'=>'Niet meetellen','Roles whose visits are not counted'=>'Rollen waarvan de bezoeken niet worden meegeteld','Visits from people logged in with a ticked role are left out of every report. Administrators are ticked by default so your own browsing does not pollute the stats; tick editors, authors or shop managers to leave out the rest of the team.'=>'Bezoeken van ingelogde mensen met een aangevinkte rol worden uit elk rapport weggelaten. Beheerders staan standaard aangevinkt, zodat je eigen surfgedrag de statistieken niet vervuilt; vink redacteuren, auteurs of winkelbeheerders aan om de rest van het team uit te sluiten.','Toolbar'=>'Werkbalk','Show today\'s pageviews in the admin toolbar.'=>'Toon de paginaweergaven van vandaag in de beheerwerkbalk.','Data retention'=>'Gegevensbewaring','Custom (%d day)'=>'Aangepast (%d dag)' . "\0" . 'Aangepast (%d dagen)','Rows in daily rollup tables older than this are purged by a daily cron job.'=>'Rijen in de dagelijkse samenvattingstabellen die ouder zijn dan dit, worden opgeschoond door een dagelijkse cron-taak.','Current usage: %1$s MB across %2$d analytics table.'=>'Huidig gebruik: %1$s MB verdeeld over %2$d analyticstabel.' . "\0" . 'Huidig gebruik: %1$s MB verdeeld over %2$d analyticstabellen.','Who can see the numbers'=>'Wie de cijfers kan zien','Roles with access'=>'Rollen met toegang','Roles that can view analytics'=>'Rollen die analytics mogen bekijken','Administrator'=>'Beheerder','(always)'=>'(altijd)','Administrators can always read the dashboard. This cannot be changed.'=>'Beheerders kunnen het dashboard altijd bekijken. Dit kan niet worden gewijzigd.','Lets someone read the dashboard without making them an administrator. Changing settings, running imports and everything destructive still needs full administrator rights.'=>'Hiermee kan iemand het dashboard bekijken zonder beheerder te worden. Instellingen wijzigen, imports uitvoeren en al het destructieve blijft volledige beheerdersrechten vereisen.','Headless front end'=>'Headless front-end','If this WordPress site is only the editor and another site (Astro, Next.js, anything else) shows the pages to readers, enter that site\'s address. Its pages can then send pageviews here, and each one is matched to the WordPress post it shows.'=>'Als deze WordPress-site alleen de editor is en een andere site (Astro, Next.js, of iets anders) de pagina\'s aan lezers toont, voer dan het adres van die site in. Die pagina\'s kunnen dan paginaweergaven hierheen sturen, en elke weergave wordt gekoppeld aan het WordPress-bericht dat wordt getoond.','Front-end site address'=>'Adres van de front-endsite','The address readers see in their browser, including https://. One site; pageviews sent from any other address are refused. Leave empty if this WordPress site serves its own pages.'=>'Het adres dat lezers in hun browser zien, inclusief https://. Eén site; paginaweergaven die vanaf een ander adres worden verzonden, worden geweigerd. Laat leeg als deze WordPress-site zelf zijn pagina\'s levert.','Add to the front end'=>'Toevoegen aan de front-end','Paste this before </body> on every page. Pages that know their WordPress post can add <meta name="vireo:post-id" content="123">; for a site that changes pages without reloading, add data-spa="history" to the tag.'=>'Plak dit vóór </body> op elke pagina. Pagina\'s die hun WordPress-bericht kennen, kunnen <meta name="vireo:post-id" content="123"> toevoegen; voor een site die van pagina wisselt zonder te herladen, voeg je data-spa="history" toe aan de tag.','Pageviews are sent to %s. Pages are matched to posts by their path, so a front end that keeps the WordPress permalink structure needs nothing else; the vireo_headless_post_id filter maps anything that differs.'=>'Paginaweergaven worden verzonden naar %s. Pagina\'s worden aan berichten gekoppeld via hun pad, dus een front-end die de WordPress-permalinkstructuur behoudt, heeft verder niets nodig; met de filter vireo_headless_post_id koppel je alles wat afwijkt.','What this cannot see'=>'Wat hier niet zichtbaar is','Crawlers and AI bots are counted when they request a page from this WordPress site. Requests they make to the front end never reach it, so the crawler figures on the dashboard cover WordPress only; your front-end host\'s logs have the rest.'=>'Crawlers en AI-bots worden geteld wanneer ze een pagina opvragen bij deze WordPress-site. Verzoeken die ze aan de front-end doen, bereiken deze site nooit, dus de crawlercijfers op het dashboard gelden alleen voor WordPress; de logs van je front-endhost bevatten de rest.','Connect Search Console for the front-end address, since that is the site Google indexes. Core Web Vitals are not collected from the front end in this version.'=>'Koppel Search Console voor het front-end-adres, want dat is de site die Google indexeert. Core Web Vitals worden in deze versie niet vanaf de front-end verzameld.','Exclusions'=>'Uitsluitingen','Skip pageviews from known bots, your own IPs, or internal paths. Bot UAs are filtered automatically; these rules run on top.'=>'Sla paginaweergaven over van bekende bots, je eigen IP-adressen of interne paden. Bot-UA\'s worden automatisch gefilterd; deze regels komen daar bovenop.','Excluded IPs / CIDR'=>'Uitgesloten IP\'s / CIDR','One entry per line. IPv4, IPv6, and CIDR ranges are supported.'=>'Eén item per regel. IPv4, IPv6 en CIDR-bereiken worden ondersteund.','Excluded paths'=>'Uitgesloten paden','One path pattern per line. Use <code>*</code> for any chars except <code>/</code>, <code>**</code> for any chars.'=>'Eén padpatroon per regel. Gebruik <code>*</code> voor alle tekens behalve <code>/</code> en <code>**</code> voor alle tekens.','Blocked referrers'=>'Geblokkeerde verwijzers','Sites whose visits are filtered like bots and hidden from reports. Known referrer spam is blocked already; these are the ones you added from a referrer row.'=>'Sites waarvan de bezoeken worden gefilterd zoals bots en verborgen blijven in rapporten. Bekende referrer-spam is al geblokkeerd; dit zijn de sites die je zelf hebt toegevoegd vanuit een verwijzerrij.','Blocked hosts'=>'Geblokkeerde hosts','One host per line; subdomains are included. Remove a line to unblock it. Blocking stops counting from now on and hides earlier rows; nothing is deleted.'=>'Eén host per regel; subdomeinen horen erbij. Verwijder een regel om de blokkade op te heffen. Blokkeren stopt het tellen vanaf nu en verbergt eerdere rijen; er wordt niets verwijderd.','Geo-location'=>'Geolocatie','Countries'=>'Landen','Resolving'=>'Wordt herleid','Your host or CDN already tells us each visitor\'s country (it reported %s for this request), so countries resolve automatically. No database needed.'=>'Je host of CDN geeft ons al het land van elke bezoeker door (voor dit verzoek werd %s gemeld), dus landen worden automatisch herleid. Geen database nodig.','Installed'=>'Geïnstalleerd','Country lookups run against the local database on this server.'=>'Landopzoekingen verlopen via de lokale database op deze server.','Geolocation by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.'=>'Geolocatie door <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.','Not resolving'=>'Wordt niet herleid','Every visitor is recorded as unknown until a country source is available. The one-click database below fixes it.'=>'Elke bezoeker wordt als onbekend vastgelegd totdat er een landbron beschikbaar is. De database met één klik hieronder lost dit op.','Download country database'=>'Landendatabase downloaden','Free, no account, installed for you. Data by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).'=>'Gratis, geen account, voor je geïnstalleerd. Gegevens door <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).','Prefer MaxMind GeoLite2? (manual)'=>'Liever MaxMind GeoLite2? (handmatig)','Create a free account at <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> and generate a license key.'=>'Maak een gratis account aan op <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> en genereer een licentiesleutel.','Download <code>GeoLite2-Country.mmdb</code> (the Country edition is enough).'=>'Download <code>GeoLite2-Country.mmdb</code> (de Country-editie is voldoende).','Upload it to <code>%s/</code> on this server.'=>'Upload het naar <code>%s/</code> op deze server.','MaxMind requires an account and prohibits automatic downloads, which is why it is manual.'=>'MaxMind vereist een account en verbiedt automatische downloads, daarom gaat het handmatig.','Excluded countries'=>'Uitgesloten landen','One two-letter country code per line. Traffic from these countries is discarded instead of counted, the same as an excluded IP. Bots that announce themselves are already filtered; this is for the traffic that does not.'=>'Eén tweeletterige landcode per regel. Verkeer uit deze landen wordt genegeerd in plaats van geteld, net als een uitgesloten IP-adres. Bots die zichzelf kenbaar maken worden al gefilterd; dit is voor het verkeer dat dat niet doet.','Needs the country to be known, so it requires either a host that resolves it or the database above.'=>'Vereist dat het land bekend is, dus dit werkt alleen met een host die dit herleidt of de database hierboven.','Excluding a country stops it being counted from now on. It does not remove what was counted before, so a report covering earlier dates still shows it.'=>'Als je een land uitsluit, wordt het vanaf nu niet meer geteld. Wat al geteld is, blijft staan, dus een rapport over eerdere datums toont het nog steeds.','Remove stored data for %s'=>'Opgeslagen gegevens voor %s verwijderen','Clears them from the countries report. Pageview and visitor totals keep those visits, because nothing else records which country a visit came from.'=>'Haalt ze uit het landenrapport. De totalen voor paginaweergaven en bezoekers houden die bezoeken, omdat niets anders bijhoudt uit welk land een bezoek kwam.','Auto-events'=>'Automatische gebeurtenissen','Record common clicks and form sends as events, with no code to add. Each one shows up on the Campaigns tab.'=>'Leg veelvoorkomende klikken en formulierverzendingen vast als gebeurtenissen, zonder code toe te voegen. Ze verschijnen op het tabblad Campagnes.','File downloads'=>'Bestandsdownloads','Record clicks on links to files (PDF, ZIP, DOC, MP3, MP4, etc.).'=>'Registreer klikken op links naar bestanden (PDF, ZIP, DOC, MP3, MP4, enz.).','Fires a "download" event with the filename as the value.'=>'Vuurt een "download"-gebeurtenis af met de bestandsnaam als waarde.','Form submissions'=>'Formulierinzendingen','Record every form submit.'=>'Registreer elke formulierinzending.','Fires a "form_submit" event with the form id, name, or action URL.'=>'Vuurt een "form_submit"-gebeurtenis af met de formulier-id, -naam of action-URL.','Email links'=>'E-maillinks','Record clicks on mailto: links.'=>'Registreer klikken op mailto:-links.','Only the part after the @ is kept, so no email address is stored.'=>'Alleen het deel na de @ wordt bewaard, dus er wordt geen e-mailadres opgeslagen.','Phone links'=>'Telefoonlinks','Record clicks on tel: links.'=>'Registreer klikken op tel:-links.','Outbound links'=>'Uitgaande links','Record clicks on links to external domains.'=>'Registreer klikken op links naar externe domeinen.','Pro records outbound clicks with more detail, so this option is off to avoid counting each click twice.'=>'Pro legt uitgaande klikken uitgebreider vast, daarom staat deze optie uit, zodat geen klik twee keer telt.','Fires an "outbound" event with the external host as the value.'=>'Vuurt een "outbound"-gebeurtenis af met de externe host als waarde.','The last day, week or month in one email: top pages, referrers and countries. It\'s built on your server and sent with your site\'s own mail.'=>'De laatste dag, week of maand in één e-mail: populairste pagina\'s, verwijzers en landen. De e-mail wordt op je server opgebouwd en verzonden met de eigen mailfunctie van je site.','Enable'=>'Inschakelen','Send the digest'=>'De samenvatting versturen','Frequency'=>'Frequentie','Every morning, covering the day before.'=>'Elke ochtend, over de dag ervoor.','Once a week, covering the last seven full days.'=>'Eén keer per week, over de laatste zeven volledige dagen.','On the first of each month, covering the month before.'=>'Op de eerste van elke maand, over de maand ervoor.','Recipients'=>'Ontvangers','One email per line. Leave blank to fall back to the site admin (%s).'=>'Eén e-mailadres per regel. Laat leeg om terug te vallen op de sitebeheerder (%s).','When'=>'Wanneer','Hour'=>'Uur','Site timezone (%s).'=>'Tijdzone van de site (%s).','Save settings'=>'Instellingen opslaan','Connected sites'=>'Gekoppelde sites','Count visits to other sites you run, whether or not they use WordPress: a static site, a docs site, a landing page. Each connected site keeps its own numbers, and the dashboard switches between them. Unlike the headless front end above, its pages are not matched to posts here.'=>'Tel bezoeken op andere sites die je beheert, met of zonder WordPress: een statische site, een documentatiesite, een landingspagina. Elke gekoppelde site houdt zijn eigen cijfers bij en het dashboard wisselt ertussen. In tegenstelling tot de headless front-end hierboven worden de pagina\'s hier niet aan berichten gekoppeld.','Paste this before </body> on every page of the site. The second line collects Core Web Vitals and can be left out. For a site that changes pages without reloading, add data-spa="history" to the first tag.'=>'Plak dit vóór </body> op elke pagina van de site. De tweede regel verzamelt Core Web Vitals en kan worden weggelaten. Voeg voor een site die van pagina wisselt zonder te herladen data-spa="history" toe aan de eerste tag.','Pageviews are accepted only when the browser sends them from %s, so the tag records nothing if it is pasted anywhere else.'=>'Paginaweergaven worden alleen geaccepteerd als de browser ze verstuurt vanaf %s, dus de tag registreert niets als je hem ergens anders plakt.','Remove this site…'=>'Deze site verwijderen…','This deletes every number recorded for %s. There is no undo. Type the site\'s name to confirm.'=>'Hiermee verwijder je alle cijfers die voor %s zijn vastgelegd. Dit kan niet ongedaan worden gemaakt. Typ de naam van de site om te bevestigen.','Site name'=>'Sitenaam','Remove site and its data'=>'Site en bijbehorende gegevens verwijderen','Keep it'=>'Behouden','Docs site'=>'Documentatiesite','Site address'=>'Siteadres','The address readers see in their browser, including https://. Visits sent from any other address are refused.'=>'Het adres dat bezoekers in hun browser zien, inclusief https://. Bezoeken die vanaf een ander adres worden verstuurd, worden geweigerd.','Connect site'=>'Site koppelen','This install allows %d connected site.'=>'Deze installatie staat %d gekoppelde site toe.' . "\0" . 'Deze installatie staat %d gekoppelde sites toe.','Bot filter test'=>'Botfiltertest','Paste a User-Agent to see whether Vireo Analytics would filter it as a bot. Useful when debugging why a visitor (or monitoring tool) isn\'t showing up in stats.'=>'Plak een User-Agent om te zien of Vireo Analytics die als bot zou filteren. Handig bij het uitzoeken waarom een bezoeker (of monitoringtool) niet in de statistieken verschijnt.','User-Agent'=>'User-Agent','Test User-Agent'=>'Test-User-Agent','Test email'=>'Testmail','Sends the digest for the last finished period to %s right now (bypasses the schedule).'=>'Verstuurt de samenvatting over de laatst afgeronde periode nu meteen naar %s (omzeilt het schema).','Send test email'=>'Testmail verzenden','Search Console'=>'Search Console','Search Console connected. The first sync runs shortly.'=>'Search Console gekoppeld. De eerste synchronisatie start binnenkort.','The last week is in. Older history is loading in the background a couple of weeks at a time, and should be complete in a few minutes.'=>'De afgelopen week is binnen. Oudere geschiedenis wordt op de achtergrond geladen, een paar weken tegelijk, en zou binnen een paar minuten compleet moeten zijn.','Search Console data refreshed.'=>'Search Console-gegevens vernieuwd.','Search Console disconnected.'=>'Search Console ontkoppeld.','Brings in the searches people ran before they arrived. Google strips the query from the referrer, so this is the only place it exists. Uses the same kind of service account key as the Analytics importer, with read-only access.'=>'Haalt de zoekopdrachten binnen die mensen deden voordat ze aankwamen. Google verwijdert de zoekopdracht uit de verwijzer, dus dit is de enige plek waar die nog bestaat. Gebruikt hetzelfde soort serviceaccountsleutel als de Analytics-importer, met alleen-lezen toegang.','Under APIs and services, enable the Google Search Console API.'=>'Schakel onder API\'s en services de Google Search Console API in.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com. You need that address for the next part.'=>'Maak onder IAM en beheer, dan Serviceaccounts, een serviceaccount aan. Het adres eindigt op .iam.gserviceaccount.com. Dat adres heb je nodig voor het volgende onderdeel.','In Search Console'=>'In Search Console','Open Settings, then Users and permissions, and add the service account address with Restricted access.'=>'Open Instellingen, dan Gebruikers en rechten, en voeg het serviceaccountadres toe met beperkte toegang.','Copy the property exactly as Search Console lists it. A domain property looks like sc-domain:example.com. A URL-prefix property is the full address including https:// and any trailing slash. The two are different properties and the wrong one returns nothing.'=>'Kopieer de property exact zoals Search Console die vermeldt. Een domeinproperty ziet er zo uit: sc-domain:example.com. Een URL-prefixproperty is het volledige adres inclusief https:// en een eventuele afsluitende slash. Dit zijn twee verschillende properties en de verkeerde levert niets op.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below.'=>'Open daarna het gedownloade bestand in een teksteditor en plak het geheel, inclusief accolades, in het vak hieronder.','The last sync failed: %s'=>'De laatste synchronisatie is mislukt: %s','Last refreshed %1$s ago, covering %2$s to %3$s.'=>'Laatst vernieuwd %1$s geleden, dekking %2$s tot %3$s.','Add %s as a user on the property in Search Console, with Restricted access.'=>'Voeg %s toe als gebruiker op de property in Search Console, met beperkte toegang.','Property'=>'Property','Copy it exactly as Search Console shows it. A domain property looks like sc-domain:example.com.'=>'Kopieer het exact zoals Search Console het toont. Een domeinproperty ziet er zo uit: sc-domain:example.com.','Save Search Console settings'=>'Search Console-instellingen opslaan','Fetch the last 90 days'=>'Haal de laatste 90 dagen op','Disconnect'=>'Ontkoppelen','PageSpeed Insights'=>'PageSpeed Insights','API key saved. Tests now run from the dashboard and show their results there.'=>'API-sleutel opgeslagen. Tests worden nu vanuit het dashboard uitgevoerd en de resultaten verschijnen daar.','API key removed.'=>'API-sleutel verwijderd.','The Page speed tab and each post\'s stats have a button for Google\'s lab test. Without a key it opens the test on the PageSpeed Insights website. With your own free Google API key, the test runs from here and the results show on the dashboard, next to the speed your real visitors got. A test only runs when someone presses the button.'=>'Het tabblad Paginasnelheid en de statistieken van elk bericht hebben een knop voor de labtest van Google. Zonder sleutel opent de test op de website van PageSpeed Insights. Met je eigen gratis Google API-sleutel wordt de test vanaf hier uitgevoerd en verschijnen de resultaten op het dashboard, naast de snelheid die je echte bezoekers hebben ervaren. Een test wordt alleen uitgevoerd als iemand op de knop drukt.','%s, or pick one you already have. Any name works.'=>'%s, of kies een project dat je al hebt. Elke naam is goed.','Create a Google Cloud project'=>'Een Google Cloud-project maken','%s for that project.'=>'%s voor dat project.','Enable the PageSpeed Insights API'=>'De PageSpeed Insights API inschakelen','On the %s page, choose Create credentials, then API key.'=>'Kies op de pagina %s eerst Inloggegevens maken en daarna API-sleutel.','Credentials'=>'Inloggegevens','Open the new key. Under API restrictions, choose Restrict key, select PageSpeed Insights API, and save.'=>'Open de nieuwe sleutel. Kies onder API-beperkingen voor Sleutel beperken, selecteer PageSpeed Insights API en sla op.','Copy the key and paste it below.'=>'Kopieer de sleutel en plak hem hieronder.','Google API key (optional)'=>'Google API-sleutel (optioneel)','A key is saved.'=>'Er is een sleutel opgeslagen.','Save API key'=>'API-sleutel opslaan','Remove API key'=>'API-sleutel verwijderen','REST API'=>'REST API','Endpoints and an example request'=>'Endpoints en een voorbeeldverzoek','Read-only endpoints under /wp-json/vireo-analytics/v1. Authenticate with WordPress Application Passwords or a logged-in session nonce. Requires the view_vireo_analytics capability.'=>'Alleen-lezen endpoints onder /wp-json/vireo-analytics/v1. Authenticeer met WordPress-applicatiewachtwoorden of een nonce van een ingelogde sessie. Vereist de capability view_vireo_analytics.','Base URL'=>'Basis-URL','Endpoints'=>'Endpoints','Example'=>'Voorbeeld','Connect an AI assistant'=>'Een AI-assistent koppelen','Ask Claude, Cursor or any other MCP client about this site\'s traffic in plain language: what changed this week, which pages are growing, what people searched for. The assistant signs in as you with an application password and sees exactly what you can see in the dashboard, read-only.'=>'Vraag Claude, Cursor of een andere MCP-client in gewone taal naar het verkeer van deze site: wat er deze week is veranderd, welke pagina\'s groeien, waar mensen naar hebben gezocht. De assistent logt als jou in met een applicatiewachtwoord en ziet precies wat jij in het dashboard ziet, alleen-lezen.','The bundled MCP adapter is missing from this install, so the endpoint is off. Reinstall the plugin from its release package.'=>'De meegeleverde MCP-adapter ontbreekt in deze installatie, dus het endpoint staat uit. Installeer de plugin opnieuw vanuit het releasepakket.','MCP endpoint'=>'MCP-endpoint','Copy'=>'Kopiëren','Application password'=>'Applicatiewachtwoord','Create one on your profile'=>'Maak er een aan in je profiel','and name it after the assistant. Paste it where the snippets below say APP_PASSWORD; the spaces WordPress shows in it can stay. You can revoke it from the same place at any time.'=>'en geef het de naam van de assistent. Plak het op de plek waar de onderstaande snippets APP_PASSWORD noemen; de spaties die WordPress erin toont mogen blijven staan. Je kunt het op dezelfde plek op elk moment intrekken.','Only users who can open the Vireo dashboard can connect. A password for anyone else is refused.'=>'Alleen gebruikers die het Vireo-dashboard kunnen openen, kunnen verbinding maken. Een wachtwoord voor iemand anders wordt geweigerd.','Claude Code'=>'Claude Code','Run it in a terminal, then ask Claude Code about your traffic.'=>'Voer dit uit in een terminal en stel Claude Code daarna vragen over je verkeer.','Claude Desktop, Cursor and others'=>'Claude Desktop, Cursor en andere','Add it to the client\'s MCP settings file (claude_desktop_config.json, Cursor\'s mcp.json). Needs Node.js on that computer; the proxy runs locally and talks to this site over HTTPS.'=>'Voeg het toe aan het MCP-instellingenbestand van de client (claude_desktop_config.json, mcp.json van Cursor). Node.js moet op die computer staan; de proxy draait lokaal en praat via HTTPS met deze site.','Import data'=>'Gegevens importeren','Bring your history into Vireo Analytics. Your source data is never modified. An import adds to what is already stored and can\'t be undone, so import any range only once.'=>'Haal je geschiedenis naar Vireo Analytics. Je brongegevens worden nooit aangepast. Een import komt bovenop wat al is opgeslagen en kan niet ongedaan worden gemaakt, dus importeer elk bereik maar één keer.','Found on this site'=>'Gevonden op deze site','A Google Analytics plugin is active on this site.'=>'Er is een Google Analytics-plugin actief op deze site.','Active, with data stored on this site.'=>'Actief, met gegevens die op deze site zijn opgeslagen.','Active on this site.'=>'Actief op deze site.','No longer active, but its data is still stored on this site.'=>'Niet meer actief, maar de gegevens staan nog op deze site.','None of the analytics plugins Vireo Analytics imports from is active on this site, and none has left data here. If you have used one of these, or still have its data elsewhere:'=>'Geen van de analyticsplugins waaruit Vireo Analytics kan importeren is actief op deze site, en geen enkele heeft hier gegevens achtergelaten. Als je er een hebt gebruikt, of de gegevens ervan elders nog hebt:','Vireo Analytics can also import from:'=>'Vireo Analytics kan ook importeren uit:','These import from the data a plugin leaves on this site. None was found yet:'=>'Deze importeren de gegevens die een plugin op deze site achterlaat. Er is nog niets gevonden:','Backup and restore'=>'Back-up en herstel','Download everything Vireo Analytics has recorded for this site as one file, and load it on another install, or back onto this one. Loading the same file twice gives the same numbers, so a restore can be repeated safely. Settings, connected sites and the live visitor buffer are not included.'=>'Download alles wat Vireo Analytics voor deze site heeft vastgelegd als één bestand en laad het op een andere installatie, of terug op deze. Hetzelfde bestand twee keer laden geeft dezelfde cijfers, dus een herstel kun je veilig herhalen. Instellingen, gekoppelde sites en de live bezoekersbuffer zijn niet inbegrepen.','Download backup'=>'Back-up downloaden','Restore from a backup'=>'Herstellen vanuit een back-up','Export CSV'=>'CSV exporteren','Download your analytics for the dates below as a CSV file. It\'s built on your server and goes straight to your browser.'=>'Download je statistieken voor de datums hieronder als CSV-bestand. Het wordt op je server gemaakt en gaat rechtstreeks naar je browser.','Site totals'=>'Sitetotalen','Pages'=>'Pagina\'s','Referrers'=>'Verwijzingen','Devices'=>'Apparaten','Broken links'=>'Verbroken links','Events'=>'Gebeurtenissen','Type'=>'Type','Download CSV'=>'CSV downloaden','Questions or a bug? %s.'=>'Vragen of een bug? %s.','Ask in the support forum'=>'Stel je vraag in het supportforum','No 404 errors in this period'=>'Geen 404-fouten in deze periode','Broken links and missing pages hit by visitors will appear here.'=>'Kapotte links en ontbrekende pagina\'s die bezoekers tegenkomen, verschijnen hier.','Path'=>'Pad','Top referrer'=>'Belangrijkste verwijzing','Hits'=>'Hits','No broken links'=>'Geen verbroken links','Nothing on your site links to a page that is missing.'=>'Niets op je site linkt naar een ontbrekende pagina.','Pages on your site linking somewhere missing. Fix the linking page.'=>'Pagina\'s op je site die linken naar iets dat ontbreekt. Herstel de linkende pagina.','Missing page'=>'Ontbrekende pagina','Linked from'=>'Gelinkt vanaf','+%s more page'=>'+%s pagina meer' . "\0" . '+%s pagina\'s meer','Requests from elsewhere'=>'Verzoeken van elders','Nothing on your site links to these. Mostly automated scanners looking for software you do not run; occasionally a stale link elsewhere worth a redirect.'=>'Niets op je site linkt hiernaar. Meestal geautomatiseerde scanners die op zoek zijn naar software die je niet draait; af en toe een verouderde link elders die een redirect waard is.','Referrer'=>'Verwijzer','no referrer'=>'geen verwijzer','requests from their crawlers'=>'verzoeken van hun crawlers','readers they sent back'=>'lezers die ze terugstuurden','crawler requests per reader sent'=>'crawlerverzoeken per doorgestuurde lezer','Since %s, when Vireo started counting crawlers. Earlier days in this range have readers but no crawler figures, so this card leaves them out.'=>'Sinds %s, toen Vireo begon met het tellen van crawlers. Eerdere dagen in deze periode hebben wel lezers maar geen crawlercijfers, dus die laat deze kaart weg.','Assistant'=>'Assistent','Readers sent'=>'Lezers verzonden','No assistant has sent a reader to this site in this period, though their crawlers have been reading it.'=>'Geen enkele assistent heeft in deze periode een lezer naar deze site gestuurd, hoewel hun crawlers de site wel hebben gelezen.','Crawler figures count requests the bot filter held back. Readers sent counts people who arrived by following a link inside an assistant, which is the closest thing there is to being recommended by one.'=>'Crawlercijfers tellen verzoeken die de botfilter heeft tegengehouden. Lezers verzonden telt mensen die aankwamen via een link binnen een assistent, wat het dichtst in de buurt komt van aanbevolen worden door een assistent.','Notes'=>'Notities','Remove the note for %s'=>'Notitie van %s verwijderen','Nothing noted in this range yet.'=>'Nog niets genoteerd in deze periode.','Date'=>'Datum','What happened'=>'Wat is er gebeurd','Newsletter went out'=>'Nieuwsbrief verstuurd','Add note'=>'Notitie toevoegen','%s request kept out of the numbers above.'=>'%s verzoek buiten de bovenstaande cijfers gehouden.' . "\0" . '%s verzoeken buiten de bovenstaande cijfers gehouden.','That is under 0.1%% of the requests Vireo saw.'=>'Dat is minder dan 0,1%% van de verzoeken die Vireo heeft gezien.','That is %s%% of the requests Vireo saw.'=>'Dat is %s%% van de verzoeken die Vireo zag.','What was filtered and why'=>'Wat er is gefilterd en waarom','None of these reached your visitor or pageview totals. It is also why those totals sit below what a server-log tool reports: log readers count every crawler, monitor and scraper as a visit. Crawlers are counted when they ask WordPress for a page, so on a site with full-page caching the real numbers are higher than these: a cached page is answered before WordPress runs, and nothing inside WordPress can see that request.'=>'Niets hiervan telt mee in je bezoekers- of paginaweergavetotalen. Dat is ook waarom die totalen lager uitvallen dan wat een serverlogtool rapporteert: logreaders tellen elke crawler, monitor en scraper als bezoek. Crawlers worden geteld wanneer ze WordPress om een pagina vragen, dus op een site met full-page caching liggen de werkelijke cijfers hoger dan deze: een gecachete pagina wordt beantwoord voordat WordPress draait, en niets binnen WordPress kan dat verzoek zien.','Got it'=>'Begrepen','Both'=>'Beide','Prior period'=>'Vorige periode','Hourly traffic'=>'Verkeer per uur','Daily traffic'=>'Verkeer per dag','Chart granularity'=>'Detailniveau van de grafiek','Chart metric'=>'Grafiekstatistiek','%s, whole days'=>'%s, hele dagen','No traffic yet'=>'Nog geen verkeer','Pageviews for the selected range will plot here as they are recorded.'=>'Paginaweergaven voor het geselecteerde bereik worden hier weergegeven zodra ze worden vastgelegd.','View'=>'Weergave','Map'=>'Kaart','Table'=>'Tabel','Countries are not being resolved'=>'Landen worden niet herleid','The geo-location database is not installed, so every visitor is recorded as unknown. Your traffic is still being counted.'=>'De geolocatiedatabase is niet geïnstalleerd, dus elke bezoeker wordt als onbekend vastgelegd. Je verkeer wordt nog steeds geteld.','Set it up'=>'Instellen','No country data yet'=>'Nog geen landgegevens','Geo-located pageviews will appear here once visitors arrive.'=>'Geolocatie-paginaweergaven verschijnen hier zodra er bezoekers komen.','World map of visitor distribution'=>'Wereldkaart van de bezoekersverdeling','Country known for %s%% of visitors.'=>'Land bekend voor %s%% van de bezoekers.','Filter by %s'=>'Filteren op %s','Device types'=>'Apparaattypen','Browsers'=>'Browsers','Operating systems'=>'Besturingssystemen','Technology breakdown'=>'Technologieverdeling','No data for this period.'=>'Geen gegevens voor deze periode.','visitor'=>'bezoeker' . "\0" . 'bezoekers','Gained'=>'Toename','Nothing grew.'=>'Niets is gegroeid.','Lost'=>'Afname','Nothing fell.'=>'Niets is gedaald.','Show all pages'=>'Alle pagina\'s tonen','Sources'=>'Bronnen','Show all sources'=>'Alle bronnen tonen','Fix this'=>'Dit oplossen','&larr; Overview'=>'&larr; Overzicht','Total count'=>'Totaalaantal','times recorded in this range'=>'keer vastgelegd in dit bereik','Unique visitors'=>'Unieke bezoekers','daily visitors, added up'=>'dagelijkse bezoekers, opgeteld','Distinct values'=>'Afzonderlijke waarden','in this range, top %d listed below'=>'in dit bereik, top %d hieronder','in this range'=>'in dit bereik','Daily counts'=>'Dagelijkse aantallen','Count'=>'Aantal','Unique'=>'Uniek','Nothing recorded in this range'=>'Niets vastgelegd in dit bereik','Event counts for the selected range will plot here as they are recorded.'=>'Gebeurtenisaantallen voor het geselecteerde bereik worden hier weergegeven zodra ze worden vastgelegd.','Top values'=>'Belangrijkste waarden','No values recorded'=>'Geen waarden vastgelegd','Send a value with this event to see a breakdown here.'=>'Stuur een waarde mee met deze gebeurtenis om hier een uitsplitsing te zien.','(no value)'=>'(geen waarde)','&larr; back to all events'=>'&larr; terug naar alle gebeurtenissen','Top events'=>'Belangrijkste gebeurtenissen','No events recorded'=>'Geen gebeurtenissen vastgelegd','Fire events from your site with <code>vireo(\'event\', \'name\')</code> and they\'ll appear here.'=>'Vuur gebeurtenissen af vanaf je site met <code>vireo(\'event\', \'name\')</code> en ze verschijnen hier.','not available with these filters'=>'niet beschikbaar met deze filters','in the selected range'=>'in het geselecteerde bereik','daily uniques, summed'=>'dagelijkse unieke bezoekers, opgeteld','unique today'=>'uniek vandaag','Someone who visits on more than one day is counted once per day. Visitors are identified by a hash whose salt is regenerated every night, so the same person cannot be recognised across days. That is deliberate: it is what lets Vireo track visitors without cookies and without consent.'=>'Iemand die op meer dan één dag langskomt, wordt per dag één keer geteld. Bezoekers worden geïdentificeerd via een hash waarvan de salt elke nacht opnieuw wordt gegenereerd, zodat dezelfde persoon niet over meerdere dagen heen herkend kan worden. Dat is bewust: het is wat Vireo in staat stelt bezoekers te volgen zonder cookies en zonder toestemming.','Unique visitors today.'=>'Unieke bezoekers vandaag.','Average daily traffic'=>'Gemiddeld verkeer per dag','over %d day'=>'over %d dag' . "\0" . 'over %d dagen','not split by filters'=>'niet gesplitst op filters','Time on page is measured for the whole site, so it is not shown while a filter is on.'=>'Tijd op pagina wordt voor de hele site gemeten, dus wordt niet getoond zolang een filter actief is.','average active time'=>'gemiddelde actieve tijd','The average of the %s view that reported a time. Only time with the tab in front of the reader counts, up to 30 minutes a view, and views closed before they reported are left out.'=>'Het gemiddelde van de %s weergave die een tijd heeft doorgegeven. Alleen tijd waarin het tabblad vooraan staat telt mee, tot maximaal 30 minuten per weergave. Weergaven die zijn gesloten voordat ze een tijd doorgaven, blijven buiten beschouwing.' . "\0" . 'Het gemiddelde van de %s weergaven die een tijd hebben doorgegeven. Alleen tijd waarin het tabblad vooraan staat telt mee, tot maximaal 30 minuten per weergave. Weergaven die zijn gesloten voordat ze een tijd doorgaven, blijven buiten beschouwing.','Time on page'=>'Tijd op de pagina','Bounce rate is measured for the whole site, so it is not shown while a filter is on.'=>'Bouncepercentage wordt voor de hele site gemeten, dus wordt niet getoond zolang een filter actief is.','visitors who viewed one page'=>'bezoekers die één pagina bekeken','The share of visitors who viewed exactly one page in a day. A visitor is counted the same way as on the Visitors card, once per day, so someone who comes back on another day counts again.'=>'Het aandeel bezoekers dat op één dag precies één pagina heeft bekeken. Een bezoeker wordt op dezelfde manier geteld als op de kaart Bezoekers: één keer per dag. Wie op een andere dag terugkomt, telt dus opnieuw mee.','Bounce rate'=>'Bouncepercentage','The %1$s figures come from history imported from %2$s.'=>'De cijfers voor %1$s komen uit geschiedenis die is geïmporteerd uit %2$s.','This week'=>'Deze week','Compared with the same period last year, up to the same time of day.'=>'Vergeleken met dezelfde periode vorig jaar, tot hetzelfde tijdstip van de dag.','Compared with the same period last year.'=>'Vergeleken met dezelfde periode vorig jaar.','Compared with the period before, up to the same time of day.'=>'Vergeleken met de periode ervoor, tot hetzelfde tijdstip van de dag.','Compared with the period before.'=>'Vergeleken met de periode ervoor.','Performance score'=>'Prestatiescore','What Google suggests fixing first'=>'Wat Google voorstelt om eerst te verhelpen','Nothing with a measurable saving. This page passed the checks that matter most.'=>'Niets met een meetbare winst. Deze pagina heeft de belangrijkste controles doorstaan.','Tested as a desktop visitor %s ago.'=>'%s geleden getest als desktopbezoeker.','Tested as a phone visitor %s ago.'=>'%s geleden getest als bezoeker op een telefoon.','Run again'=>'Opnieuw uitvoeren','Full report on PageSpeed Insights'=>'Volledig rapport op PageSpeed Insights','(opens in a new tab)'=>'(opent in een nieuw tabblad)','Lab: one test by Google'=>'Lab: één test door Google','Device to test as'=>'Apparaat om mee te testen','Test this page on PageSpeed Insights'=>'Deze pagina testen met PageSpeed Insights','Add a free Google API key in Settings to see the results right here instead.'=>'Voeg bij Instellingen een gratis Google API-sleutel toe om de resultaten in plaats daarvan hier te zien.','An administrator can add a free Google API key in Settings to show the results right here instead.'=>'Een beheerder kan in de instellingen een gratis Google API-sleutel toevoegen om de resultaten in plaats daarvan direct hier te tonen.','Google loads this page once on its own servers, as a desktop visitor, and lists what would make it faster. It takes up to a minute.'=>'Google laadt deze pagina één keer op zijn eigen servers, als desktopbezoeker, en toont wat de pagina sneller zou maken. Dit duurt maximaal een minuut.','Google loads this page once on its own servers, as a phone visitor on a slow connection, and lists what would make it faster. It takes up to a minute.'=>'Google laadt deze pagina één keer op zijn eigen servers, als bezoeker op een telefoon met een trage verbinding, en toont wat de pagina sneller zou maken. Dit duurt maximaal een minuut.','Run test'=>'Test uitvoeren','Lifetime pageviews'=>'Paginaweergaven aller tijden','since %s'=>'sinds %s','Lifetime visitors'=>'Bezoekers aller tijden','Best day'=>'Beste dag','no traffic yet'=>'nog geen verkeer','Daily traffic · %1$s &ndash; %2$s'=>'Verkeer per dag · %1$s &ndash; %2$s','No traffic in this range'=>'Geen verkeer in dit bereik','Pageviews for this post will plot here as they are recorded.'=>'Paginaweergaven voor dit bericht worden hier weergegeven zodra ze worden vastgelegd.','pageviews in range'=>'paginaweergaven in bereik','visitors in range'=>'bezoekers in bereik','comment in range'=>'reactie in periode' . "\0" . 'reacties in periode','comments per 1,000 views'=>'reacties per 1.000 weergaven','Page speed for this post'=>'Paginasnelheid voor dit bericht','Speed from your real visitors is measured for the whole site, not per post.'=>'De snelheid van je echte bezoekers wordt voor de hele site gemeten, niet per bericht.','See it on the Overview'=>'Bekijk het in het Overzicht','This post, tested by Google'=>'Dit bericht, getest door Google','Test this post with Google'=>'Dit bericht testen met Google','Top referrers for this post'=>'Belangrijkste verwijzingen voor dit bericht','No referrers in this range'=>'Geen verwijzingen in dit bereik','This post had no inbound referrers during the selected period.'=>'Dit bericht had geen inkomende verwijzingen tijdens de geselecteerde periode.','Per-post referrer data is being collected'=>'Verwijzingsgegevens per bericht worden verzameld','Referrers per individual post started tracking with a recent update. Data will appear here as new visitors arrive.'=>'Verwijzingen per afzonderlijk bericht worden sinds een recente update bijgehouden. Gegevens verschijnen hier zodra er nieuwe bezoekers komen.','Referrer data for this post starts from %s.'=>'Verwijzingsgegevens voor dit bericht beginnen vanaf %s.','Searches that found this post'=>'Zoekopdrachten die dit bericht vonden','See what people searched for'=>'Bekijk waar mensen op zochten','Only Search Console knows which searches showed this post. Connect it to list them here.'=>'Alleen Search Console weet bij welke zoekopdrachten dit bericht verscheen. Koppel het om ze hier te zien.','Connect Search Console'=>'Search Console koppelen','No searches for this post in this range'=>'Geen zoekopdrachten voor dit bericht in dit bereik','Google reports search data about three days late, so the most recent days are always empty.'=>'Google publiceert zoekgegevens ongeveer drie dagen later, dus de meest recente dagen zijn altijd leeg.','Clicks · position'=>'Klikken · positie','Shown %s time'=>'%s keer getoond' . "\0" . '%s keer getoond','%1$s. Printed %2$s from Vireo Analytics.'=>'%1$s. Afgedrukt op %2$s vanuit Vireo Analytics.','Traffic from this referrer · %1$s to %2$s'=>'Verkeer van deze verwijzing · %1$s tot %2$s','Pageviews in range'=>'Paginaweergaven in bereik','Visitors in range'=>'Bezoekers in bereik','No traffic from this referrer in this range'=>'Geen verkeer van deze verwijzing in dit bereik','Pageviews sent by this source will plot here as they are recorded.'=>'Paginaweergaven van deze bron worden hier weergegeven zodra ze worden vastgelegd.','Posts it sent people to'=>'Berichten waar het bezoekers naartoe stuurde','Pageviews on each post from this referrer. Home and archive pages aren\'t broken down this way.'=>'Paginaweergaven per bericht vanaf deze verwijzer. De homepage en archiefpagina’s worden zo niet uitgesplitst.','Vireo has been counting here for %s day. If it has been useful, a review on WordPress.org helps other site owners find it.'=>'Vireo telt hier al %s dag mee. Als het nuttig is geweest, helpt een beoordeling op WordPress.org andere site-eigenaren om het te vinden.' . "\0" . 'Vireo telt hier al %s dagen mee. Als het nuttig is geweest, helpt een beoordeling op WordPress.org andere site-eigenaren om het te vinden.','Leave a review'=>'Laat een beoordeling achter','Not now'=>'Niet nu','Don\'t ask again'=>'Niet meer vragen','Searches that found you'=>'Zoekopdrachten die je vonden','clicks from search'=>'klikken vanuit zoekresultaten','times you appeared'=>'keer verschenen','click-through rate'=>'klikfrequentie','average position'=>'gemiddelde positie','Clicks'=>'Klikken','Impressions'=>'Vertoningen','Position'=>'Positie','The page Google most often showed for this search'=>'De pagina die Google het vaakst voor deze zoekopdracht toonde','From Search Console, which reports a few days behind and leaves out rare searches.'=>'Van Search Console, dat een paar dagen vertraging heeft en zeldzame zoekopdrachten weglaat.','posts opened'=>'geopende berichten','links followed from a post'=>'links gevolgd vanuit een bericht','Follow clicks'=>'Volgklikken','Load more clicks'=>'Klikken op Meer laden','Instagram feeds'=>'Instagram-feeds','Page with a feed'=>'Pagina met een feed','Posts opened'=>'Geopende berichten','No pages tracked yet'=>'Nog geen pagina\'s bijgehouden','Top posts and pages will appear here after the first few visits.'=>'Topberichten en -pagina\'s verschijnen hier na de eerste paar bezoeken.','Average active time on this page: %s'=>'Gemiddelde actieve tijd op deze pagina: %s','(unpublished)'=>'(niet gepubliceerd)','Visitors who arrived with no referrer: typed the URL, used a bookmark, or came from an app or email client.'=>'Bezoekers die zonder verwijzing binnenkwamen: typten de URL, gebruikten een bladwijzer of kwamen via een app of e-mailclient.','No search traffic in this range.'=>'Geen zoekverkeer in dit bereik.','No AI assistant traffic in this range.'=>'Geen verkeer van AI-assistenten in dit bereik.','No social traffic in this range.'=>'Geen social-verkeer in dit bereik.','No referral traffic in this range.'=>'Geen verwijzingsverkeer in dit bereik.','No referrers yet'=>'Nog geen verwijzingen','When someone clicks through from another site, they\'ll show up here.'=>'Wanneer iemand doorklikt vanaf een andere site, verschijnt die hier.','None of these made the top ten. Filter by this source to list them.'=>'Geen hiervan haalde de top tien. Filter op deze bron om ze weer te geven.','Every visit from this site viewed one page and none landed on a post, over a burst of days. That is what a compromised site or a spoofed referrer looks like, not readers. Nothing is removed until you block it.'=>'Elk bezoek vanaf deze site bekeek één pagina en belandde op geen enkel bericht, verspreid over een reeks dagen. Zo ziet een gehackte site of een vervalste verwijzer eruit, niet echte lezers. Er wordt niets verwijderd totdat je het blokkeert.','suspected junk'=>'vermoedelijke spam','Block this referrer'=>'Deze verwijzer blokkeren','Page speed from real visits'=>'Paginasnelheid uit echte bezoeken','No speed measurements from real visits in this range yet. They appear as people load your pages.'=>'Nog geen snelheidsmetingen van echte bezoeken in deze periode. Ze verschijnen zodra mensen je pagina\'s laden.','75th percentile: three in four visits were at least this fast.'=>'75e percentiel: drie op de vier bezoeken waren minstens zo snel.','Google grades pages on this line rather than the average, so the slowest quarter of visits counts against you.'=>'Google beoordeelt pagina\'s op deze waarde in plaats van het gemiddelde, dus het traagste kwart van de bezoeken telt tegen je.','Only %s real visit measured so far, so expect these to move.'=>'Nog maar %s echt bezoek gemeten, dus deze waarden kunnen nog veranderen.' . "\0" . 'Nog maar %s echte bezoeken gemeten, dus deze waarden kunnen nog veranderen.','Measured from %s real visit, not a lab test.'=>'Gemeten op basis van %s echt bezoek, niet in een labtest.' . "\0" . 'Gemeten op basis van %s echte bezoeken, niet in een labtest.','Your homepage, tested by Google'=>'Je homepage, getest door Google','Test your homepage with Google'=>'Je homepage testen met Google','Aggregated content'=>'Geaggregeerde content','views of imported posts'=>'weergaven van geïmporteerde berichten','clicks through to the original articles'=>'klikken door naar de oorspronkelijke artikelen','of all pageviews were imported posts'=>'van alle paginaweergaven waren geïmporteerde berichten','Feed source'=>'Feedbron','Views here'=>'Weergaven hier','Clicks out'=>'Uitgaande klikken','Clicks out count readers who followed an item to the site it came from, recorded from the day this version of Vireo was installed.'=>'Uitgaande klikken tellen lezers die een item naar de site volgden waar het vandaan komt, vastgelegd vanaf de dag waarop deze versie van Vireo is geïnstalleerd.','Views here count visits to items imported as posts.'=>'Weergaven hier tellen bezoeken aan items die als berichten zijn geïmporteerd.','Your %d in review is ready.'=>'Je terugblik op %d is klaar.','See it'=>'Bekijken','%d so far'=>'%d tot nu toe','%d in review'=>'Terugblik %d','vs the same days of %d'=>'t.o.v. dezelfde dagen in %d','vs %d'=>'t.o.v. %d','No full record of %d to compare with'=>'Geen volledig overzicht van %d om mee te vergelijken','Year'=>'Jaar','Copy summary'=>'Samenvatting kopiëren','Print'=>'Afdrukken','Nothing recorded for %d yet'=>'Nog niets geregistreerd voor %d','This review fills in on its own as visits are recorded; the first ones show up within a minute. If another analytics tool counted this year, its history can be imported and shows here marked as imported.'=>'Dit overzicht vult zich vanzelf naarmate bezoeken worden vastgelegd; de eerste verschijnen binnen een minuut. Telde een andere analysetool dit jaar, dan kun je die geschiedenis importeren en verschijnt die hier als geïmporteerd.','Import history'=>'Geschiedenis importeren','Part of one year was imported from another tool, which counts in its own way, so read the change as a rough guide.'=>'Een deel van één jaar is geïmporteerd uit een andere tool, die op een eigen manier telt. Zie de verandering daarom als een grove indicatie.','Daily visitors added up. Someone who came on three different days counts three times, because Vireo can\'t recognise anyone from one day to the next.'=>'Dagelijkse bezoekers bij elkaar opgeteld. Iemand die op drie verschillende dagen kwam, telt drie keer, omdat Vireo niemand van de ene dag op de andere kan herkennen.','Busiest month'=>'Drukste maand','Busiest day: %1$s, with %2$s pageview.'=>'Drukste dag: %1$s, met %2$s paginaweergave.' . "\0" . 'Drukste dag: %1$s, met %2$s paginaweergaven.','Pageviews by month'=>'Paginaweergaven per maand','still to come'=>'nog te komen','%s pageviews so far this month'=>'%s paginaweergaven tot nu toe deze maand','%s pageviews, imported'=>'%s paginaweergaven, geïmporteerd','%1$s pageviews, %2$s of them imported'=>'%1$s paginaweergaven, waarvan %2$s geïmporteerd','%s pageviews'=>'%s paginaweergaven','so far'=>'tot nu toe','Counted by Vireo Analytics'=>'Geteld door Vireo Analytics','Imported'=>'Geïmporteerd','Where these numbers come from'=>'Waar deze cijfers vandaan komen','%1$s pageviews this year came from imports and %2$s were counted by Vireo. Imported months are as the other tool counted them, which rarely matches Vireo exactly: tools filter bots and count visitors differently.'=>'%1$s paginaweergaven dit jaar komen uit imports en %2$s zijn door Vireo geteld. Geïmporteerde maanden staan zoals de andere tool ze telde, wat zelden exact overeenkomt met Vireo: tools filteren bots en tellen bezoekers op een andere manier.','No page-level data for this year.'=>'Geen gegevens op paginaniveau voor dit jaar.','Published in %d'=>'Gepubliceerd in %d','Nothing published this year has been viewed yet.'=>'Er is nog niets bekeken van wat dit jaar is gepubliceerd.','Countries from %s onward. Earlier history has no country data.'=>'Landen vanaf %s. Eerdere geschiedenis heeft geen landgegevens.','Visitors, added up day by day.'=>'Bezoekers, dag voor dag opgeteld.','No country data for this year.'=>'Geen landgegevens voor dit jaar.','How people arrived, in pageviews'=>'Hoe bezoekers binnenkwamen, in paginaweergaven','mostly %1$s (%2$s)'=>'vooral %1$s (%2$s)','No referrer data for this year.'=>'Geen verwijzergegevens voor dit jaar.','Top Google searches'=>'Top Google-zoekopdrachten','%1$s clicks from %2$s appearances in Google results.'=>'%1$s klikken uit %2$s vermeldingen in Google-resultaten.','requests from AI crawlers'=>'verzoeken van AI-crawlers','readers sent back'=>'lezers teruggestuurd','Since %s, when Vireo started counting. Imported history doesn\'t record crawlers, so earlier months are left out of both numbers.'=>'Sinds %s, toen Vireo begon met tellen. Geïmporteerde geschiedenis registreert geen crawlers, dus eerdere maanden zijn uit beide cijfers weggelaten.','%s crawler requests for every reader sent.'=>'%s crawlerverzoeken per doorgestuurde lezer.','Your day on %s'=>'Jouw dag op %s','Your daily snapshot · %s'=>'Jouw dagoverzicht · %s','change against the previous dayDoD'=>'DoD','Your month on %s'=>'Jouw maand op %s','Your monthly snapshot · %s'=>'Jouw maandoverzicht · %s','change against the previous monthMoM'=>'MoM','Your week on %s'=>'Jouw week op %s','Your weekly snapshot · %s'=>'Jouw weekoverzicht · %s','change against the previous weekWoW'=>'WoW','Every minute (Vireo Analytics)'=>'Elke minuut (Vireo Analytics)','%s event'=>'%s gebeurtenis' . "\0" . '%s gebeurtenissen','Daily traffic chart, no data.'=>'Grafiek verkeer per dag, geen gegevens.','Daily traffic, %1$s to %2$s. %3$s, %4$s. Use arrow keys to step through each day.'=>'Dagelijks verkeer, %1$s tot %2$s. %3$s, %4$s. Gebruik de pijltjestoetsen om door elke dag te stappen.','%1$s: %2$s, %3$s'=>'%1$s: %2$s, %3$s',', %s pageview in the prior period'=>', %s paginaweergave in de voorgaande periode' . "\0" . ', %s paginaweergaven in de voorgaande periode','Note: %s'=>'Notitie: %s','Note on %1$s: %2$s'=>'Notitie bij %1$s: %2$s','%1$s: %2$s'=>'%1$s: %2$s